        ["hud.a_terra_aiuto"] = new[] { "Un alleato può rialzarti", "An ally can revive you", "Un aliado puede levantarte", "Un allié peut te relever", "Ein Verbündeter kann dich aufrichten", "Um aliado pode te levantar", "Союзник может поднять тебя", "队友可以扶起你" },
        ["hud.spettatore"] = new[] { "Spettatore: torni in gioco quando finisce lo scontro", "Spectating: you return when the fight ends", "Espectador: vuelves cuando termine el combate", "Spectateur : tu reviens à la fin du combat", "Zuschauer: Du kehrst nach dem Kampf zurück", "Espectador: você volta quando a luta acabar", "Наблюдатель: вернёшься, когда бой закончится", "观战中：战斗结束后返回" },
        ["hud.gruppo_sconfitto"] = new[] { "Tutto il gruppo è caduto", "The whole party has fallen", "Todo el grupo ha caído", "Tout le groupe est tombé", "Die ganze Gruppe ist gefallen", "Todo o grupo caiu", "Вся группа пала", "全队倒下" },
        ["pg.prova"] = new[] { "Maren", "Maren", "Maren", "Maren", "Maren", "Maren", "Марен", "玛伦" },
        ["dlg.prova.1"] = new[] { "Eccoti, finalmente. Per parlarmi hai premuto {Interagisci}.", "There you are, at last. You pressed {Interagisci} to talk to me.", "Por fin llegas. Para hablar conmigo has pulsado {Interagisci}.", "Te voilà enfin. Pour me parler, tu as appuyé sur {Interagisci}.", "Da bist du endlich. Zum Sprechen hast du {Interagisci} gedrückt.", "Até que enfim. Para falar comigo você apertou {Interagisci}.", "Наконец-то ты здесь. Чтобы поговорить со мной, ты нажал {Interagisci}.", "你终于来了。你按下了 {Interagisci} 来和我说话。" },
        ["dlg.prova.2"] = new[] { "(Frase di prova: se leggi questa riga il sistema dei dialoghi funziona.)", "(Test line: if you can read this, the dialogue system works.)", "(Línea de prueba: si lees esto, el sistema de diálogos funciona.)", "(Ligne de test : si tu lis ceci, le système de dialogues fonctionne.)", "(Testzeile: Wenn du das liest, funktioniert das Dialogsystem.)", "(Linha de teste: se você lê isto, o sistema de diálogos funciona.)", "(Тестовая строка: если вы это читаете, система диалогов работает.)", "(测试句:如果你看到这一行,对话系统就能正常工作。)" },
        ["pg.maren"] = new[] { "Maren", "Maren", "Maren", "Maren", "Maren", "Maren", "Марен", "玛伦" },
        ["pg.tobin"] = new[] { "Tobin", "Tobin", "Tobin", "Tobin", "Tobin", "Tobin", "Тобин", "托宾" },
        ["pg.brannoc"] = new[] { "Brannoc", "Brannoc", "Brannoc", "Brannoc", "Brannoc", "Brannoc", "Бреннок", "布兰诺克" },
        ["pg.edric"] = new[] { "Edric", "Edric", "Edric", "Edric", "Edric", "Edric", "Эдрик", "埃德里克" },
        ["pg.hobb"] = new[] { "Hobb", "Hobb", "Hobb", "Hobb", "Hobb", "Hobb", "Хобб", "霍布" },
        ["pg.ilse"] = new[] { "Ilse", "Ilse", "Ilse", "Ilse", "Ilse", "Ilse", "Ильзе", "伊尔莎" },
        ["dlg.q1.01"] = new[] { "Papà, papà! Il sole è già alto e tu dormi ancora!", "Dad, Dad! The sun is already high and you're still asleep!", "¡Papá, papá! ¡El sol ya está alto y tú sigues durmiendo!", "Papa, papa ! Le soleil est déjà haut et tu dors encore !", "Papa, Papa! Die Sonne steht schon hoch und du schläfst noch!", "Pai, pai! O sol já está alto e você ainda está dormindo!", "Папа, папа! Солнце уже высоко, а ты всё спишь!", "爸爸，爸爸！太阳都升得那么高了，你还在睡！" },
        ["dlg.q1.02"] = new[] { "Lascialo, ha sognato di nuovo il lago. Lo so dalla faccia.", "Leave him be, he dreamed of the lake again. I can tell from his face.", "Déjalo, ha vuelto a soñar con el lago. Se le nota en la cara.", "Laisse-le, il a encore rêvé du lac. Ça se voit sur son visage.", "Lass ihn, er hat wieder vom See geträumt. Das sehe ich ihm an.", "Deixe ele, sonhou com o lago de novo. Dá para ver pela cara.", "Оставь его, ему опять приснилось озеро. Это видно по лицу.", "别吵他，他又梦见湖了。看他的脸就知道。" },
        ["dlg.q1.03"] = new[] { "(L'eroe si alza.)", "(The hero gets up.)", "(El héroe se levanta.)", "(Le héros se lève.)", "(Der Held steht auf.)", "(O herói se levanta.)", "(Герой встаёт.)", "(英雄起身了。)" },
        ["dlg.q1.04"] = new[] { "Eccoti, finalmente. Il fuoco si sta spegnendo e il capanno è pieno di legna che nessuno porta dentro.", "There you are, at last. The fire is dying down and the shed is full of wood that nobody brings in.", "Por fin te levantas. El fuego se está apagando y el cobertizo está lleno de leña que nadie trae.", "Te voilà enfin. Le feu s'éteint et le cabanon est plein de bois que personne ne rentre.", "Da bist du ja endlich. Das Feuer geht aus und der Schuppen ist voller Holz, das niemand hereinholt.", "Até que enfim. O fogo está se apagando e o galpão está cheio de lenha que ninguém traz para dentro.", "Наконец-то. Огонь гаснет, а сарай полон дров, которые никто не приносит.", "你总算起来了。火快灭了，棚子里堆满了柴，却没人搬进来。" },
        ["dlg.q1.05"] = new[] { "Posso venire anch'io? Io porto i pezzi piccoli!", "Can I come too? I'll carry the small pieces!", "¿Puedo ir yo también? ¡Yo llevo los trozos pequeños!", "Je peux venir aussi ? Je porte les petits morceaux !", "Darf ich auch mitkommen? Ich trage die kleinen Stücke!", "Posso ir também? Eu levo os pedaços pequenos!", "Можно мне с тобой? Я понесу маленькие поленья!", "我也能去吗？小块的我来搬！" },
        ["dlg.q1.06"] = new[] { "Resta dove ti vedo, ometto. Il lago oggi è strano: ha un colore più scuro del solito.", "Stay where I can see you, little man. The lake looks strange today: darker than usual.", "Quédate donde te vea, hombrecito. Hoy el lago está raro: más oscuro de lo normal.", "Reste là où je te vois, petit homme. Le lac est étrange aujourd'hui : plus sombre que d'habitude.", "Bleib, wo ich dich sehen kann, kleiner Mann. Der See ist heute seltsam: dunkler als sonst.", "Fique onde eu possa te ver, homenzinho. O lago está estranho hoje: mais escuro que de costume.", "Оставайся там, где я тебя вижу, малыш. Озеро сегодня странное: темнее обычного.", "待在我看得到的地方，小家伙。今天的湖有点怪，颜色比平时更深。" },
        ["dlg.q1.07"] = new[] { "Prendi la legna, poi passa dal fabbro. Brannoc ha detto che ti cercava. Non fargli aspettare, ha un carattere peggio di un tasso.", "Fetch the wood, then stop by the smith. Brannoc said he was looking for you. Don't keep him waiting, he has a temper worse than a badger's.", "Trae la leña y luego pasa por el herrero. Brannoc dijo que te buscaba. No le hagas esperar, tiene peor carácter que un tejón.", "Va chercher le bois, puis passe voir le forgeron. Brannoc te cherchait. Ne le fais pas attendre, il a un caractère pire que celui d'un blaireau.", "Hol das Holz und geh dann zum Schmied. Brannoc hat nach dir gefragt. Lass ihn nicht warten, er hat ein Temperament schlimmer als ein Dachs.", "Pegue a lenha e depois passe no ferreiro. O Brannoc disse que estava te procurando. Não o faça esperar, ele tem um gênio pior que o de um texugo.", "Принеси дрова, потом зайди к кузнецу. Бреннок тебя искал. Не заставляй его ждать, у него характер хуже, чем у барсука.", "先把柴搬进来，再去找铁匠。布兰诺克说他在找你。别让他等，他的脾气比獾还差。" },
        ["dlg.q1.08"] = new[] { "Quella è troppo grossa! Tienila tu, io faccio la guardia.", "That one is too big! You take it, I'll keep watch.", "¡Esa es demasiado grande! Llévala tú, yo hago la guardia.", "Celle-là est trop grosse ! Prends-la, moi je monte la garde.", "Das ist zu groß! Nimm du es, ich halte Wache.", "Essa é grande demais! Leve você, eu fico de guarda.", "Это слишком большое! Бери ты, а я постою на страже.", "那根太大了！你拿吧，我来放哨。" },
        ["dlg.q1.09"] = new[] { "Bravo. Adesso vai, prima che Brannoc si metta a gridare.", "Well done. Now go, before Brannoc starts shouting.", "Muy bien. Ahora ve, antes de que Brannoc se ponga a gritar.", "Bravo. Maintenant va, avant que Brannoc ne se mette à crier.", "Gut gemacht. Jetzt geh, bevor Brannoc anfängt zu schreien.", "Muito bem. Agora vá, antes que o Brannoc comece a gritar.", "Молодец. А теперь иди, пока Бреннок не начал кричать.", "做得好。快去吧，免得布兰诺克大喊大叫。" },
        ["tip.q1.muovi"] = new[] { "Muoviti con {Avanti} {Sinistra} {Indietro} {Destra}. Gira la camera con il mouse.", "Move with {Avanti} {Sinistra} {Indietro} {Destra}. Turn the camera with the mouse.", "Muévete con {Avanti} {Sinistra} {Indietro} {Destra}. Gira la cámara con el ratón.", "Déplace-toi avec {Avanti} {Sinistra} {Indietro} {Destra}. Oriente la caméra avec la souris.", "Bewege dich mit {Avanti} {Sinistra} {Indietro} {Destra}. Drehe die Kamera mit der Maus.", "Mova-se com {Avanti} {Sinistra} {Indietro} {Destra}. Gire a câmera com o mouse.", "Двигайся клавишами {Avanti} {Sinistra} {Indietro} {Destra}. Камеру поворачивай мышью.", "用 {Avanti} {Sinistra} {Indietro} {Destra} 移动，用鼠标转动镜头。" },
        ["tip.q1.parla"] = new[] { "Avvicinati a una persona e premi {Interagisci} per parlarle.", "Walk up to a person and press {Interagisci} to talk.", "Acércate a una persona y pulsa {Interagisci} para hablar con ella.", "Approche-toi d'une personne et appuie sur {Interagisci} pour lui parler.", "Geh zu einer Person und drücke {Interagisci}, um mit ihr zu sprechen.", "Aproxime-se de uma pessoa e aperte {Interagisci} para falar com ela.", "Подойди к человеку и нажми {Interagisci}, чтобы поговорить.", "走近一个人，按 {Interagisci} 和他交谈。" },
        ["ob.q1.legna"] = new[] { "Porta la legna dal capanno a casa", "Bring the wood from the shed to the house", "Lleva la leña del cobertizo a casa", "Rapporte le bois du cabanon à la maison", "Bring das Holz vom Schuppen ins Haus", "Leve a lenha do galpão para casa", "Отнеси дрова из сарая домой", "把柴从棚子搬回家" },
        ["ob.q1.fabbro"] = new[] { "Vai dal fabbro Brannoc", "Go to Brannoc the smith", "Ve a ver al herrero Brannoc", "Va voir le forgeron Brannoc", "Geh zum Schmied Brannoc", "Vá ao ferreiro Brannoc", "Иди к кузнецу Бренноку", "去找铁匠布兰诺克" },
        ["dlg.q2.01g"] = new[] { "Sei in ritardo. Non importa. Prendi questa: una lama vecchia, ma ancora buona.", "You're late. Never mind. Take this: an old blade, but still a good one.", "Llegas tarde. No importa. Toma esto: una hoja vieja, pero todavía buena.", "Tu es en retard. Peu importe. Prends ceci : une vieille lame, mais encore bonne.", "Du bist spät dran. Egal. Nimm das: eine alte Klinge, aber noch gut.", "Você está atrasado. Não importa. Pegue isto: uma lâmina velha, mas ainda boa.", "Опаздываешь. Неважно. Держи: клинок старый, но ещё хороший.", "你来晚了。算了。拿着：一把旧剑，但还能用。" },
        ["dlg.q2.01l"] = new[] { "Sei in ritardo. Non importa. Prendi questi: un pugnale e un arco vecchi, ma ancora buoni.", "You're late. Never mind. Take these: an old dagger and an old bow, but still good ones.", "Llegas tarde. No importa. Toma esto: un puñal y un arco viejos, pero todavía buenos.", "Tu es en retard. Peu importe. Prends ça : une dague et un arc, vieux mais encore bons.", "Du bist spät dran. Egal. Nimm die hier: ein alter Dolch und ein alter Bogen, aber noch gut.", "Você está atrasado. Não importa. Pegue isto: um punhal e um arco velhos, mas ainda bons.", "Опаздываешь. Неважно. Держи: кинжал и лук, старые, но ещё хорошие.", "你来晚了。算了。拿着：一把匕首和一张弓，旧是旧了，还能用。" },
        ["dlg.q2.01s"] = new[] { "Sei in ritardo. Non importa. Il ferro non è mai stato roba tua: il vecchio Edric ti aspetta al tempio.", "You're late. Never mind. Iron was never your thing: old Edric is waiting for you at the temple.", "Llegas tarde. No importa. El hierro nunca fue lo tuyo: el viejo Edric te espera en el templo.", "Tu es en retard. Peu importe. Le fer n'a jamais été ton affaire : le vieil Edric t'attend au temple.", "Du bist spät dran. Egal. Eisen war nie dein Ding: Der alte Edric wartet im Tempel auf dich.", "Você está atrasado. Não importa. O ferro nunca foi coisa sua: o velho Edric está te esperando no templo.", "Опаздываешь. Неважно. Железо никогда не было твоим делом: старый Эдрик ждёт тебя в храме.", "你来晚了。算了。打铁从来不是你的事：老埃德里克在神殿等你。" },
        ["dlg.q2.02"] = new[] { "Dicono che gli orchi si fanno vedere nei boschi. Io non ci credo, ma un uomo con una lama in mano dorme meglio.", "They say orcs have been seen in the woods. I don't believe it, but a man with a blade in his hand sleeps better.", "Dicen que se han visto orcos en los bosques. Yo no me lo creo, pero un hombre con una hoja en la mano duerme mejor.", "On dit que des orcs rôdent dans les bois. Je n'y crois pas, mais un homme une lame à la main dort mieux.", "Man sagt, in den Wäldern seien Orks gesehen worden. Ich glaube es nicht, aber ein Mann mit einer Klinge in der Hand schläft besser.", "Dizem que viram orcs nos bosques. Eu não acredito, mas um homem com uma lâmina na mão dorme melhor.", "Говорят, в лесах видели орков. Я не верю, но человек с клинком в руке спит спокойнее.", "听说有人在林子里看见了兽人。我不信，但手里握着刀的人睡得更踏实。" },
        ["dlg.q2.03"] = new[] { "Vediamo se sai ancora stare in piedi. Il manichino non si muove, ma tu sì.", "Let's see if you can still stand on your feet. The dummy doesn't move, but you do.", "Veamos si todavía te tienes en pie. El muñeco no se mueve, pero tú sí.", "Voyons si tu tiens encore debout. Le mannequin ne bouge pas, mais toi, si.", "Mal sehen, ob du dich noch auf den Beinen halten kannst. Die Puppe bewegt sich nicht, aber du schon.", "Vamos ver se você ainda se aguenta de pé. O boneco não se mexe, mas você sim.", "Посмотрим, держишься ли ты ещё на ногах. Чучело не двигается, а ты — да.", "看看你还站不站得稳。木人不会动，但你会。" },
        ["dlg.q2.04"] = new[] { "Non male. Hai la mano di uno che non ha dimenticato.", "Not bad. You have the hand of someone who hasn't forgotten.", "Nada mal. Tienes la mano de quien no ha olvidado.", "Pas mal. Tu as la main de quelqu'un qui n'a pas oublié.", "Nicht schlecht. Du hast die Hand von einem, der nichts vergessen hat.", "Nada mal. Você tem a mão de quem não esqueceu.", "Неплохо. У тебя рука того, кто ничего не забыл.", "不错。你这手，是没忘本的人的手。" },
        ["dlg.q2.05"] = new[] { "L'arco è bravo quando chi lo tiene è fermo. Tu muoviti, ma tira quando respiri.", "A bow is good when the one holding it is still. You keep moving, but shoot when you breathe.", "El arco es bueno cuando quien lo sostiene está quieto. Tú muévete, pero dispara cuando respires.", "L'arc est bon quand celui qui le tient est immobile. Bouge, mais tire quand tu respires.", "Ein Bogen taugt, wenn der, der ihn hält, stillsteht. Beweg dich, aber schieß, wenn du atmest.", "O arco é bom quando quem o segura está parado. Você se mexe, mas atira quando respira.", "Лук хорош, когда тот, кто его держит, неподвижен. Ты двигайся, но стреляй на выдохе.", "持弓的人站稳了，弓才好使。你尽管走动，但要在呼吸时放箭。" },
        ["dlg.q2.06"] = new[] { "Se hai voglia di fare un po' di pratica ancora, il manichino è tuo. Poi vai dai ratti: Hobb dice che il granaio ne è pieno.", "If you feel like practising a bit more, the dummy is yours. Then go deal with the rats: Hobb says the granary is full of them.", "Si quieres practicar un poco más, el muñeco es tuyo. Luego ve a por las ratas: Hobb dice que el granero está lleno.", "Si tu veux t'entraîner encore un peu, le mannequin est à toi. Ensuite, va voir les rats : Hobb dit que le grenier en est plein.", "Wenn du noch ein bisschen üben willst, gehört die Puppe dir. Dann kümmer dich um die Ratten: Hobb sagt, der Kornspeicher ist voll davon.", "Se quiser treinar mais um pouco, o boneco é seu. Depois vá atrás dos ratos: o Hobb diz que o celeiro está cheio deles.", "Если хочешь ещё потренироваться, чучело твоё. Потом займись крысами: Хобб говорит, амбар ими кишит.", "要是还想多练练，木人归你了。然后去对付老鼠吧：霍布说谷仓里全是。" },
        ["dlg.q2s.01"] = new[] { "Ti ho visto passare davanti al tempio per tre anni senza mai entrare. Eppure sei qui.", "I've watched you walk past the temple for three years without ever coming in. And yet here you are.", "Te he visto pasar delante del templo durante tres años sin entrar nunca. Y sin embargo, aquí estás.", "Je t'ai vu passer devant le temple pendant trois ans sans jamais entrer. Et pourtant te voilà.", "Drei Jahre lang habe ich dich am Tempel vorbeigehen sehen, ohne dass du je eingetreten bist. Und doch bist du hier.", "Vi você passar em frente ao templo por três anos sem nunca entrar. E, no entanto, aqui está você.", "Три года я видел, как ты проходишь мимо храма и ни разу не входишь. И всё же ты здесь.", "三年来，我看着你从神殿门前走过，从没进来过。可你今天来了。" },
        ["dlg.q2s.02"] = new[] { "Maren mi ha detto che ti manca. Che di notte muovi le dita come se tenessi qualcosa.", "Maren told me you miss it. That at night you move your fingers as if you were holding something.", "Maren me dijo que lo echas de menos. Que de noche mueves los dedos como si sostuvieras algo.", "Maren m'a dit que ça te manque. Que la nuit tu bouges les doigts comme si tu tenais quelque chose.", "Maren hat mir erzählt, dass es dir fehlt. Dass du nachts die Finger bewegst, als hieltest du etwas.", "A Maren me disse que você sente falta. Que à noite você mexe os dedos como se segurasse alguma coisa.", "Марен сказала мне, что ты скучаешь по этому. Что ночью ты шевелишь пальцами, будто что-то держишь.", "玛伦告诉我，你很想念它。说你夜里会动手指，像是握着什么东西。" },
        ["dlg.q2s.03"] = new[] { "Non ti chiedo di rompere il tuo giuramento. Ti chiedo solo di ricordarti come si fa. Prendi questo bastone: l'ho tenuto da parte per anni.", "I'm not asking you to break your oath. I'm only asking you to remember how it's done. Take this staff: I've kept it aside for years.", "No te pido que rompas tu juramento. Solo te pido que recuerdes cómo se hace. Toma este báculo: lo he guardado durante años.", "Je ne te demande pas de rompre ton serment. Je te demande seulement de te rappeler comment on fait. Prends ce bâton : je l'ai gardé de côté pendant des années.", "Ich verlange nicht, dass du deinen Schwur brichst. Ich bitte dich nur, dich zu erinnern, wie es geht. Nimm diesen Stab: Ich habe ihn jahrelang aufbewahrt.", "Não peço que você quebre o seu juramento. Só peço que se lembre de como se faz. Pegue este cajado: guardei-o por anos.", "Я не прошу тебя нарушить клятву. Я прошу лишь вспомнить, как это делается. Возьми этот посох: я берёг его много лет.", "我不是要你违背誓言。只是想让你记起该怎么做。拿着这根法杖，我替你留了好多年。" },
        ["dlg.q2s.04"] = new[] { "Uno studioso non ha paura del fuoco, ha paura di non saperlo governare. Prova con la Scintilla.", "A scholar isn't afraid of fire; he's afraid of not being able to master it. Try the Spark.", "Un estudioso no teme al fuego, teme no saber dominarlo. Prueba con la Chispa.", "Un érudit n'a pas peur du feu, il a peur de ne pas savoir le maîtriser. Essaie l'Étincelle.", "Ein Gelehrter fürchtet nicht das Feuer, sondern es nicht beherrschen zu können. Versuch es mit dem Funken.", "Um estudioso não tem medo do fogo, tem medo de não saber dominá-lo. Tente a Fagulha.", "Учёный не боится огня — он боится не суметь его обуздать. Попробуй Искру.", "学者不怕火，怕的是驾驭不了它。试试火花吧。" },
        ["dlg.q2s.05"] = new[] { "Poi il ghiaccio. L'acqua del lago ha una memoria: ascolta quella.", "Then the ice. The water of the lake has a memory: listen to it.", "Después, el hielo. El agua del lago tiene memoria: escúchala.", "Ensuite, la glace. L'eau du lac a une mémoire : écoute-la.", "Dann das Eis. Das Wasser des Sees hat ein Gedächtnis: Hör ihm zu.", "Depois, o gelo. A água do lago tem memória: escute-a.", "Потом лёд. У воды озера есть память: прислушайся к ней.", "然后是冰。湖水有记忆，去倾听它。" },
        ["dlg.q2s.06"] = new[] { "Bene. Ricordi tutto. È come tornare a casa, vero?", "Good. You remember everything. It's like coming home, isn't it?", "Bien. Lo recuerdas todo. Es como volver a casa, ¿verdad?", "Bien. Tu te souviens de tout. C'est comme rentrer à la maison, n'est-ce pas ?", "Gut. Du erinnerst dich an alles. Es ist, als käme man nach Hause, nicht wahr?", "Muito bem. Você se lembra de tudo. É como voltar para casa, não é?", "Хорошо. Ты всё помнишь. Это как вернуться домой, правда?", "很好。你全都记得。就像回家一样，对吧？" },
        ["dlg.q2s.07"] = new[] { "Tienilo. Non so se ti servirà. Spero di no.", "Keep it. I don't know if you'll need it. I hope not.", "Quédatelo. No sé si te hará falta. Espero que no.", "Garde-le. Je ne sais pas si tu en auras besoin. J'espère que non.", "Behalte ihn. Ich weiß nicht, ob du ihn brauchen wirst. Ich hoffe nicht.", "Fique com ele. Não sei se vai precisar. Espero que não.", "Оставь его себе. Не знаю, понадобится ли он тебе. Надеюсь, что нет.", "留着吧。不知道你用不用得上。但愿用不上。" },
        ["tip.q2.attacca"] = new[] { "Attacca con {Attacca}. Costa resistenza.", "Attack with {Attacca}. It costs stamina.", "Ataca con {Attacca}. Cuesta aguante.", "Attaque avec {Attacca}. Cela coûte de l'endurance.", "Greif mit {Attacca} an. Das kostet Ausdauer.", "Ataque com {Attacca}. Custa vigor.", "Атакуй: {Attacca}. Это тратит выносливость.", "按 {Attacca} 攻击，会消耗体力。" },
        ["tip.q2.para"] = new[] { "Tieni premuto {Para} per parare. Un colpo parato fa meno danno.", "Hold {Para} to block. A blocked hit deals less damage.", "Mantén pulsado {Para} para bloquear. Un golpe bloqueado hace menos daño.", "Maintiens {Para} pour parer. Un coup paré fait moins de dégâts.", "Halte {Para} gedrückt, um zu blocken. Ein geblockter Treffer richtet weniger Schaden an.", "Segure {Para} para bloquear. Um golpe bloqueado causa menos dano.", "Удерживай {Para}, чтобы парировать. Парированный удар наносит меньше урона.", "按住 {Para} 格挡。被格挡的攻击伤害更低。" },
        ["tip.q2.schiva"] = new[] { "Premi {Schiva} per schivare. Per un attimo i colpi non ti toccano.", "Press {Schiva} to dodge. For a moment, hits can't touch you.", "Pulsa {Schiva} para esquivar. Durante un instante los golpes no te alcanzan.", "Appuie sur {Schiva} pour esquiver. Pendant un instant, les coups ne t'atteignent pas.", "Drücke {Schiva}, um auszuweichen. Einen Moment lang treffen dich keine Schläge.", "Aperte {Schiva} para esquivar. Por um instante os golpes não te atingem.", "Нажми {Schiva}, чтобы увернуться. На мгновение удары тебя не задевают.", "按 {Schiva} 闪避。短时间内攻击碰不到你。" },
        ["tip.q2.aggancia"] = new[] { "Premi {Aggancia} per agganciare il bersaglio. Premilo di nuovo per sganciarlo.", "Press {Aggancia} to lock on to a target. Press it again to release.", "Pulsa {Aggancia} para fijar el objetivo. Vuelve a pulsarlo para soltarlo.", "Appuie sur {Aggancia} pour verrouiller la cible. Appuie de nouveau pour la libérer.", "Drücke {Aggancia}, um ein Ziel anzuvisieren. Drücke erneut, um es zu lösen.", "Aperte {Aggancia} para travar no alvo. Aperte de novo para soltar.", "Нажми {Aggancia}, чтобы захватить цель. Нажми ещё раз, чтобы отпустить.", "按 {Aggancia} 锁定目标，再按一次解除。" },
        ["tip.q2.cambia_bersaglio"] = new[] { "Con un bersaglio agganciato, muovi il mouse verso un altro nemico per passare a lui.", "With a target locked, flick the mouse towards another enemy to switch to it.", "Con un objetivo fijado, mueve el ratón hacia otro enemigo para cambiar a él.", "Avec une cible verrouillée, déplace la souris vers un autre ennemi pour passer à lui.", "Bewege bei anvisiertem Ziel die Maus zu einem anderen Gegner, um zu ihm zu wechseln.", "Com um alvo travado, mova o mouse em direção a outro inimigo para mudar para ele.", "Захватив цель, резко двинь мышь в сторону другого врага, чтобы переключиться на него.", "锁定目标后，把鼠标朝另一个敌人一甩，即可切换到他。" },
        ["tip.q2.arco"] = new[] { "Premi 2 per prendere l'arco. Tieni premuto {Attacca} per tenderlo e lascia per tirare. Con 1 torni al pugnale.", "Press 2 to take out the bow. Hold {Attacca} to draw it and release to shoot. Press 1 to go back to the dagger.", "Pulsa 2 para sacar el arco. Mantén pulsado {Attacca} para tensarlo y suelta para disparar. Con 1 vuelves al puñal.", "Appuie sur 2 pour prendre l'arc. Maintiens {Attacca} pour le bander et relâche pour tirer. Avec 1, tu reprends la dague.", "Drücke 2, um den Bogen zu nehmen. Halte {Attacca} gedrückt, um ihn zu spannen, und lass los, um zu schießen. Mit 1 nimmst du wieder den Dolch.", "Aperte 2 para pegar o arco. Segure {Attacca} para puxar a corda e solte para atirar. Com 1 você volta ao punhal.", "Нажми 2, чтобы взять лук. Удерживай {Attacca}, чтобы натянуть тетиву, и отпусти, чтобы выстрелить. Клавиша 1 — снова кинжал.", "按 2 取出弓。按住 {Attacca} 拉弓，松开即放箭。按 1 换回匕首。" },
        ["tip.q2s.lancia"] = new[] { "Lancia un incantesimo con {Attacca}. Ogni incantesimo costa mana.", "Cast a spell with {Attacca}. Every spell costs mana.", "Lanza un hechizo con {Attacca}. Cada hechizo cuesta maná.", "Lance un sort avec {Attacca}. Chaque sort coûte du mana.", "Wirke mit {Attacca} einen Zauber. Jeder Zauber kostet Mana.", "Lance um feitiço com {Attacca}. Cada feitiço custa mana.", "Применяй заклинание: {Attacca}. Каждое заклинание тратит ману.", "按 {Attacca} 施放法术。每个法术都消耗法力。" },
        ["tip.q2s.cambia"] = new[] { "Cambia incantesimo con la rotellina o con i tasti da 1 a 6.", "Switch spells with the mouse wheel or the keys 1 to 6.", "Cambia de hechizo con la rueda del ratón o con las teclas del 1 al 6.", "Change de sort avec la molette ou les touches 1 à 6.", "Wechsle den Zauber mit dem Mausrad oder den Tasten 1 bis 6.", "Troque de feitiço com a rodinha do mouse ou com as teclas de 1 a 6.", "Меняй заклинание колёсиком мыши или клавишами от 1 до 6.", "用鼠标滚轮或数字键 1 到 6 切换法术。" },
        ["tip.q2s.mana"] = new[] { "La barra blu è il mana: si ricarica da solo poco dopo l'ultimo incantesimo.", "The blue bar is mana: it refills on its own shortly after your last spell.", "La barra azul es el maná: se recarga sola poco después del último hechizo.", "La barre bleue, c'est le mana : il se recharge tout seul peu après le dernier sort.", "Der blaue Balken ist das Mana: Es lädt sich kurz nach dem letzten Zauber von selbst auf.", "A barra azul é o mana: ele se recarrega sozinho pouco depois do último feitiço.", "Синяя полоса — это мана: она восстанавливается сама вскоре после последнего заклинания.", "蓝色条是法力：最后一次施法后不久会自行恢复。" },
        ["tip.q2s.distanza"] = new[] { "Fai qualche passo indietro: lo Stregone resiste meglio a distanza.", "Take a few steps back: the Sorcerer holds up better at a distance.", "Da unos pasos atrás: el Hechicero aguanta mejor a distancia.", "Recule de quelques pas : le Sorcier tient mieux à distance.", "Geh ein paar Schritte zurück: Der Hexer hält auf Abstand besser durch.", "Dê alguns passos para trás: o Feiticeiro resiste melhor à distância.", "Отойди на пару шагов: Чародею легче держаться на расстоянии.", "后退几步：术士在远处更能撑住。" },
        ["nem.ratto"] = new[] { "Ratto gigante", "Giant rat", "Rata gigante", "Rat géant", "Riesenratte", "Rato gigante", "Гигантская крыса", "巨鼠" },
        ["nem.manichino"] = new[] { "Manichino", "Training dummy", "Muñeco de práctica", "Mannequin d'entraînement", "Übungspuppe", "Boneco de treino", "Тренировочное чучело", "训练假人" },
        ["nem.sagoma"] = new[] { "Sagoma di tiro", "Archery target", "Diana de tiro", "Cible de tir", "Zielscheibe", "Alvo de tiro", "Мишень", "箭靶" },
        ["ob.q3.granaio"] = new[] { "Vai al granaio di Hobb, sul lago", "Go to Hobb's barn by the lake", "Ve al granero de Hobb, junto al lago", "Va à la grange de Hobb, au bord du lac", "Geh zu Hobbs Scheune am See", "Vá ao celeiro de Hobb, perto do lago", "Иди к амбару Хобба у озера", "去湖边霍布的谷仓" },
        ["ob.q3.ratti"] = new[] { "Ratti rimasti nel granaio: {0}", "Rats left in the barn: {0}", "Ratas que quedan en el granero: {0}", "Rats restants dans la grange : {0}", "Ratten in der Scheune: noch {0}", "Ratos restantes no celeiro: {0}", "Крыс в амбаре осталось: {0}", "谷仓里剩下的老鼠：{0}" },
        ["dlg.q3.01"] = new[] { "Eccoti! Ho un granaio che sembra un campo di battaglia e dei ratti grossi come cani.", "There you are! My barn looks like a battlefield, and the rats are as big as dogs.", "¡Por fin! Tengo un granero que parece un campo de batalla y ratas grandes como perros.", "Te voilà ! Ma grange ressemble à un champ de bataille, et les rats sont gros comme des chiens.", "Da bist du ja! Meine Scheune sieht aus wie ein Schlachtfeld, und die Ratten sind so groß wie Hunde.", "Aí está você! Meu celeiro parece um campo de batalha, e os ratos são do tamanho de cães.", "Наконец-то! Мой амбар похож на поле битвы, а крысы там размером с собаку.", "你可来了！我的谷仓简直像个战场，老鼠大得跟狗一样。" },
        ["dlg.q3.02"] = new[] { "Un tempo non erano così. Da quando il lago è diventato più scuro, tutto quello che vive vicino all'acqua è... cresciuto.", "They weren't like this once. Ever since the lake turned darker, everything living near the water has... grown.", "Antes no eran así. Desde que el lago se volvió más oscuro, todo lo que vive cerca del agua ha... crecido.", "Ils n'étaient pas comme ça, avant. Depuis que le lac s'est assombri, tout ce qui vit près de l'eau a... grandi.", "Früher waren sie nicht so. Seit der See dunkler geworden ist, ist alles, was am Wasser lebt, ... gewachsen.", "Antes não eram assim. Desde que o lago ficou mais escuro, tudo o que vive perto da água... cresceu.", "Раньше они такими не были. С тех пор как озеро потемнело, всё, что живёт у воды, ...выросло.", "它们以前可不是这样。自从湖水变暗，水边的一切都……长大了。" },
        ["dlg.q3.03"] = new[] { "Sono tre. Toglimeli di torno tutti e tre, e stanotte forse dormo.", "There are three of them. Get rid of all three, and maybe tonight I'll sleep.", "Son tres. Quítamelas de encima a las tres y quizá esta noche duerma.", "Ils sont trois. Débarrasse-moi des trois, et peut-être que je dormirai cette nuit.", "Es sind drei. Schaff mir alle drei vom Hals, dann schlafe ich heute Nacht vielleicht.", "São três. Livre-se dos três, e talvez eu durma esta noite.", "Их трое. Избавь меня от всех троих, и, может, сегодня ночью я посплю.", "一共三只。把三只都给我解决掉，今晚我也许能睡个好觉。" },
        ["dlg.q3.04"] = new[] { "Un grazie sentito. Domani ti offro una birra... anzi no, domani te ne offro due!", "My heartfelt thanks. Tomorrow the beer's on me... no, make that two!", "Te lo agradezco de corazón. Mañana te invito a una cerveza... ¡no, mejor a dos!", "Merci du fond du cœur. Demain je t'offre une bière... non, deux !", "Herzlichen Dank. Morgen geb ich dir ein Bier aus ... nein, zwei!", "Muito obrigado, de coração. Amanhã eu te pago uma cerveja... não, duas!", "Сердечное спасибо. Завтра угощаю тебя пивом... нет, двумя кружками!", "衷心感谢。明天我请你喝一杯啤酒……不，请你两杯！" },
        ["tip.q3.resistenza"] = new[] { "Ogni azione costa resistenza. Se la barra è vuota, aspetta che si ricarichi.", "Every action costs stamina. If the bar is empty, wait for it to refill.", "Cada acción cuesta resistencia. Si la barra está vacía, espera a que se recargue.", "Chaque action coûte de l'endurance. Si la barre est vide, attends qu'elle se recharge.", "Jede Aktion kostet Ausdauer. Ist die Leiste leer, warte, bis sie sich füllt.", "Cada ação custa resistência. Se a barra estiver vazia, espere ela recarregar.", "Каждое действие тратит выносливость. Если полоса пуста, подожди, пока она восстановится.", "每个动作都消耗耐力。耐力条空了，就等它恢复。" },
        ["tip.q3.schiva"] = new[] { "Quando un ratto si acquatta e diventa rosso sta per balzare: schiva con {Schiva} o para con {Para}.", "When a rat crouches and turns red, it is about to pounce: dodge with {Schiva} or block with {Para}.", "Cuando una rata se agazapa y se vuelve roja, va a saltar: esquiva con {Schiva} o bloquea con {Para}.", "Quand un rat s'accroupit et devient rouge, il va bondir : esquive avec {Schiva} ou pare avec {Para}.", "Duckt sich eine Ratte und wird rot, springt sie gleich: weiche mit {Schiva} aus oder blocke mit {Para}.", "Quando um rato se agacha e fica vermelho, vai saltar: esquive com {Schiva} ou bloqueie com {Para}.", "Когда крыса пригибается и краснеет, она сейчас прыгнет: уклонись ({Schiva}) или парируй ({Para}).", "老鼠伏低身子变红时就要扑过来了：用 {Schiva} 闪避，或用 {Para} 格挡。" },
        ["comando.usaoggetto"] = new[] { "Usa oggetto", "Use item", "Usar objeto", "Utiliser un objet", "Gegenstand benutzen", "Usar item", "Использовать предмет", "使用物品" },
        ["comando.cambiaoggetto"] = new[] { "Cambia oggetto", "Switch item", "Cambiar objeto", "Changer d'objet", "Gegenstand wechseln", "Trocar item", "Сменить предмет", "切换物品" },
        ["comando_breve.usaoggetto"] = new[] { "Usa", "Use", "Usar", "Utiliser", "Benutzen", "Usar", "Исп.", "使用" },
