        ["inv.rapido"] = new[] { "Pronto all'uso: premi {UsaOggetto} in partita", "Ready to use: press {UsaOggetto} in game", "Listo para usar: pulsa {UsaOggetto} en partida", "Prêt à l'emploi : appuie sur {UsaOggetto} en jeu", "Bereit: drücke im Spiel {UsaOggetto}", "Pronto para usar: aperte {UsaOggetto} no jogo", "Готово к использованию: нажми {UsaOggetto} в игре", "已就绪：游戏中按 {UsaOggetto} 使用" },
        ["inv.missione"] = new[] { "Serve per una missione: non si equipaggia", "Needed for a quest: it can't be equipped", "Sirve para una misión: no se puede equipar", "Sert pour une quête : ne s'équipe pas", "Für einen Auftrag: kann nicht ausgerüstet werden", "Serve para uma missão: não pode ser equipado", "Нужно для задания: экипировать нельзя", "任务物品：无法装备" },
        ["inv.quantita"] = new[] { "Quantità", "Amount", "Cantidad", "Quantité", "Anzahl", "Quantidade", "Количество", "数量" },
