        ["tipo.missione"] = new[] { "Oggetto della missione", "Quest item", "Objeto de misión", "Objet de quête", "Auftragsgegenstand", "Item de missão", "Предмет задания", "任务物品" },
        ["hud.niente_da_usare"] = new[] { "Non hai niente da usare", "You have nothing to use", "No tienes nada que usar", "Tu n'as rien à utiliser", "Du hast nichts zum Benutzen", "Você não tem nada para usar", "Нечего использовать", "没有可用的物品" },
        ["hud.cambia_oggetto"] = new[] { "cambia", "switch", "cambiar", "changer", "wechseln", "trocar", "сменить", "切换" },
        ["oggetto.pozione_di_ilse.nome"] = new[] { "Pozione di Ilse", "Ilse's Potion", "Poción de Ilse", "Potion d'Ilse", "Ilses Trank", "Poção de Ilse", "Зелье Ильзе", "伊尔莎的药水" },
        ["oggetto.pozione_di_ilse.descrizione"] = new[] { "Un intruglio rosso scuro che sa di radici e miele. Ridà vita in un attimo.", "A dark red brew that tastes of roots and honey. Restores health in a moment.", "Un brebaje rojo oscuro que sabe a raíces y miel. Devuelve la vida en un instante.", "Une décoction rouge sombre au goût de racines et de miel. Rend de la vie en un instant.", "Ein dunkelroter Sud, der nach Wurzeln und Honig schmeckt. Gibt im Nu Leben zurück.", "Uma mistura vermelho-escura com gosto de raízes e mel. Devolve vida num instante.", "Тёмно-красный отвар со вкусом корней и мёда. Мгновенно восстанавливает здоровье.", "一种暗红色的药汤，有草根和蜂蜜的味道。能迅速恢复生命。" },
        ["oggetto.fiore_di_riva.nome"] = new[] { "Fiore di riva", "Shore flower", "Flor de orilla", "Fleur de rive", "Uferblume", "Flor da margem", "Прибрежный цветок", "岸花" },
        ["oggetto.fiore_di_riva.descrizione"] = new[] { "Petali pallidi che brillano appena. Cresce solo dove l'acqua del lago è nera.", "Pale petals with a faint glow. It only grows where the lake water is black.", "Pétalos pálidos que apenas brillan. Solo crece donde el agua del lago es negra.", "Des pétales pâles qui luisent à peine. Elle ne pousse que là où l'eau du lac est noire.", "Blasse, schwach leuchtende Blütenblätter. Wächst nur dort, wo das Seewasser schwarz ist.", "Pétalas pálidas que mal brilham. Só cresce onde a água do lago é negra.", "Бледные, едва светящиеся лепестки. Растёт только там, где вода озера чёрная.", "淡淡发光的苍白花瓣。只生长在湖水发黑的地方。" },
        ["ob.q4.ilse"] = new[] { "Vai dall'erborista Ilse", "Go to Ilse the herbalist", "Ve a ver a Ilse, la herbolaria", "Va voir Ilse l'herboriste", "Geh zur Kräuterfrau Ilse", "Vá até a herbalista Ilse", "Иди к травнице Ильзе", "去找草药师伊尔莎" },
        ["ob.q4.fiori"] = new[] { "Fiori di riva raccolti: {0}/3", "Shore flowers picked: {0}/3", "Flores de orilla recogidas: {0}/3", "Fleurs de rive cueillies : {0}/3", "Uferblumen gepflückt: {0}/3", "Flores da margem colhidas: {0}/3", "Собрано прибрежных цветов: {0}/3", "已采集岸花：{0}/3" },
        ["ob.q4.torna"] = new[] { "Porta i fiori a Ilse", "Bring the flowers to Ilse", "Lleva las flores a Ilse", "Apporte les fleurs à Ilse", "Bring die Blumen zu Ilse", "Leve as flores para Ilse", "Отнеси цветы Ильзе", "把花带给伊尔莎" },
        ["ob.q4.bevi"] = new[] { "Bevi una pozione: premi {UsaOggetto}", "Drink a potion: press {UsaOggetto}", "Bebe una poción: pulsa {UsaOggetto}", "Bois une potion : appuie sur {UsaOggetto}", "Trink einen Trank: drücke {UsaOggetto}", "Beba uma poção: aperte {UsaOggetto}", "Выпей зелье: нажми {UsaOggetto}", "喝一瓶药水：按 {UsaOggetto}" },
        ["dlg.dopo.maren"] = new[] { "Grazie per la legna. Stasera la casa sarà calda... e Tobin non fa che raccontare a tutti quanto sei forte.", "Thanks for the wood. The house will be warm tonight... and Tobin keeps telling everyone how strong you are.", "Gracias por la leña. Esta noche la casa estará caliente... y Tobin no para de contarle a todo el mundo lo fuerte que eres.", "Merci pour le bois. Ce soir la maison sera chaude... et Tobin ne cesse de raconter à tout le monde à quel point tu es fort.", "Danke für das Holz. Heute Abend wird das Haus warm sein... und Tobin erzählt allen, wie stark du bist.", "Obrigada pela lenha. Hoje à noite a casa vai estar quentinha... e o Tobin não para de contar para todo mundo como você é forte.", "Спасибо за дрова. Вечером в доме будет тепло... а Тобин всем рассказывает, какой ты сильный.", "谢谢你的柴火。今晚屋里会很暖和……托宾逢人就说你有多强壮。" },
        ["dlg.dopo.brannoc"] = new[] { "Hai ancora la mano buona, te l'ho detto. Il manichino è lì se vuoi sfogarti: io torno al mio ferro.", "You've still got a good hand, I told you. The dummy's there if you want to let off steam: I'm going back to my iron.", "Todavía tienes buena mano, ya te lo dije. El maniquí está ahí si quieres desahogarte: yo vuelvo a mi hierro.", "Tu as encore la main sûre, je te l'avais dit. Le mannequin est là si tu veux te défouler : moi, je retourne à mon fer.", "Du hast immer noch eine gute Hand, hab ich doch gesagt. Die Puppe steht da, wenn du Dampf ablassen willst: Ich geh zurück an mein Eisen.", "Você ainda tem a mão boa, eu disse. O boneco está ali se quiser desabafar: eu volto para o meu ferro.", "Рука у тебя ещё крепкая, я же говорил. Чучело там, если захочешь выпустить пар, а я вернусь к своему железу.", "我说过，你的手艺还没丢。想出出气，木人桩就在那儿；我回去打我的铁了。" },
        ["dlg.dopo.brannoc_s"] = new[] { "Edric ti ha rimesso in mano quel bastone, eh? Stai attento: il fuoco non perdona chi se ne dimentica.", "Edric put that staff back in your hands, eh? Careful: fire doesn't forgive those who forget it.", "Edric te ha vuelto a poner ese bastón en la mano, ¿eh? Ten cuidado: el fuego no perdona a quien lo olvida.", "Edric t'a remis ce bâton entre les mains, hein ? Fais attention : le feu ne pardonne pas à ceux qui l'oublient.", "Edric hat dir den Stab wieder in die Hand gedrückt, was? Pass auf: Das Feuer verzeiht keinem, der es vergisst.", "O Edric colocou aquele cajado de volta na sua mão, hein? Cuidado: o fogo não perdoa quem se esquece dele.", "Эдрик снова вручил тебе этот посох, а? Осторожнее: огонь не прощает тех, кто о нём забывает.", "埃德里克又把那根法杖塞回你手里了，嗯？小心点：火可不会原谅忘了它的人。" },
        ["dlg.dopo.edric"] = new[] { "Torna quando vuoi. Il tempio è silenzioso, ma non è vuoto.", "Come back whenever you like. The temple is silent, but it isn't empty.", "Vuelve cuando quieras. El templo está en silencio, pero no está vacío.", "Reviens quand tu veux. Le temple est silencieux, mais il n'est pas vide.", "Komm wieder, wann du willst. Der Tempel ist still, aber er ist nicht leer.", "Volte quando quiser. O templo é silencioso, mas não está vazio.", "Приходи, когда захочешь. В храме тихо, но он не пуст.", "随时回来。神殿很安静，但并不空。" },
        ["dlg.dopo.edric_altri"] = new[] { "Brannoc dice che hai ancora la mano ferma. Bene: di questi tempi una lama vale più di una preghiera.", "Brannoc says your hand is still steady. Good: these days a blade is worth more than a prayer.", "Brannoc dice que todavía tienes el pulso firme. Bien: en estos tiempos una hoja vale más que una plegaria.", "Brannoc dit que ta main est encore ferme. Tant mieux : par les temps qui courent, une lame vaut plus qu'une prière.", "Brannoc sagt, deine Hand ist noch ruhig. Gut: In diesen Zeiten ist eine Klinge mehr wert als ein Gebet.", "O Brannoc diz que sua mão ainda é firme. Ótimo: hoje em dia uma lâmina vale mais que uma oração.", "Браннок говорит, рука у тебя всё ещё твёрдая. Хорошо: в наши дни клинок стоит больше молитвы.", "布兰诺克说你的手还很稳。很好：这年头，一把刀比一句祷告更管用。" },
        ["dlg.dopo.hobb"] = new[] { "Il granaio è di nuovo mio, grazie a te! Quelle monete te le sei guadagnate tutte... e le due birre non me le scordo.", "The barn is mine again, thanks to you! You earned every one of those coins... and I won't forget the two beers.", "¡El granero vuelve a ser mío, gracias a ti! Te ganaste todas esas monedas... y no me olvido de las dos cervezas.", "Le grenier est de nouveau à moi, grâce à toi ! Tu as bien mérité ces pièces... et je n'oublie pas les deux bières.", "Die Scheune gehört wieder mir, dank dir! Die Münzen hast du dir redlich verdient... und die zwei Bier vergesse ich nicht.", "O celeiro é meu de novo, graças a você! Você mereceu cada uma daquelas moedas... e não esqueço as duas cervejas.", "Амбар снова мой, благодаря тебе! Ты честно заработал те монеты... и про две кружки пива я не забуду.", "多亏了你，粮仓又归我了！那些金币你挣得一点不亏……那两杯啤酒我也记着呢。" },
        ["zona.cripta"] = new[] { "Cripta della prima guardia", "Crypt of the First Guard", "Cripta de la primera guardia", "Crypte de la première garde", "Gruft der ersten Wache", "Cripta da primeira guarda", "Склеп первой стражи", "初代守卫墓穴" },
        ["car.caricamento"] = new[] { "Caricamento", "Loading", "Cargando", "Chargement", "Wird geladen", "Carregando", "Загрузка", "加载中" },
        ["hud.entra_cripta"] = new[] { "Entra nella cripta", "Enter the crypt", "Entrar en la cripta", "Entrer dans la crypte", "Gruft betreten", "Entrar na cripta", "Войти в склеп", "进入墓穴" },
        ["hud.esci_cripta"] = new[] { "Esci dalla cripta", "Leave the crypt", "Salir de la cripta", "Sortir de la crypte", "Gruft verlassen", "Sair da cripta", "Выйти из склепа", "离开墓穴" },
        ["hud.cancello_chiuso"] = new[] { "Il cancello è chiuso. Da qualche parte ci sarà un meccanismo.", "The gate is shut. There must be a mechanism somewhere.", "La reja está cerrada. Debe de haber un mecanismo en algún sitio.", "La grille est fermée. Il doit y avoir un mécanisme quelque part.", "Das Gitter ist zu. Irgendwo muss es einen Mechanismus geben.", "O portão está fechado. Deve haver um mecanismo em algum lugar.", "Решётка заперта. Где-то должен быть механизм.", "铁门紧闭。附近一定有机关。" },
        ["nem.scheletro"] = new[] { "Scheletro vivente", "Living skeleton", "Esqueleto viviente", "Squelette vivant", "Lebendes Skelett", "Esqueleto vivo", "Живой скелет", "活骷髅" },
        ["dlg.q5.01"] = new[] { "Chiedono sempre perché il lago è nero. Nessuno chiede mai da quanto tempo.", "They always ask why the lake is black. No one ever asks for how long.", "Siempre preguntan por qué el lago es negro. Nadie pregunta desde cuándo.", "On demande toujours pourquoi le lac est noir. Personne ne demande depuis quand.", "Alle fragen, warum der See schwarz ist. Niemand fragt, seit wann.", "Sempre perguntam por que o lago é negro. Ninguém pergunta desde quando.", "Все спрашивают, почему озеро чёрное. Никто не спрашивает, с каких пор.", "人们总问湖水为什么是黑的，却从没人问它黑了多久。" },
        ["dlg.q5.02"] = new[] { "I nostri antenati non costruirono qui il villaggio per caso. Sotto il lago dorme qualcosa, e loro erano la guardia.", "Our ancestors didn't build the village here by chance. Something sleeps beneath the lake, and they were its guard.", "Nuestros antepasados no construyeron aquí la aldea por casualidad. Algo duerme bajo el lago, y ellos eran la guardia.", "Nos ancêtres n'ont pas bâti le village ici par hasard. Quelque chose dort sous le lac, et ils en étaient la garde.", "Unsere Vorfahren haben das Dorf nicht zufällig hier gebaut. Unter dem See schläft etwas, und sie waren seine Wache.", "Nossos antepassados não construíram a vila aqui por acaso. Algo dorme sob o lago, e eles eram a guarda.", "Наши предки построили деревню здесь не случайно. Под озером что-то спит, а они были его стражей.", "我们的祖先在这里建村并非偶然。湖底沉睡着某样东西，而他们就是守卫。" },
        ["dlg.q5.03"] = new[] { "Nella cripta, sotto il cimitero, c'è un oggetto che ci ha lasciato la prima guardia. Non l'ho mai preso. Non ho mai avuto il coraggio.", "In the crypt beneath the graveyard lies something the first guard left us. I never took it. I never had the courage.", "En la cripta, bajo el cementerio, hay algo que nos dejó la primera guardia. Nunca lo cogí. Nunca tuve valor.", "Dans la crypte, sous le cimetière, il y a un objet que nous a laissé la première garde. Je ne l'ai jamais pris. Je n'en ai jamais eu le courage.", "In der Gruft unter dem Friedhof liegt etwas, das uns die erste Wache hinterlassen hat. Ich habe es nie geholt. Ich hatte nie den Mut.", "Na cripta, sob o cemitério, há algo que a primeira guarda nos deixou. Nunca o peguei. Nunca tive coragem.", "В склепе под кладбищем лежит вещь, оставленная нам первой стражей. Я так и не взял её. Не хватило смелости.", "墓地下的墓穴里，有一件初代守卫留给我们的东西。我从没去拿过，我从没有那份勇气。" },
        ["dlg.q5.04"] = new[] { "L'hai trovato. È bello da vedere, non è vero? Sembra quasi vivo.", "You found it. Beautiful, isn't it? It almost seems alive.", "Lo encontraste. Es hermoso, ¿verdad? Casi parece vivo.", "Tu l'as trouvé. Il est beau, n'est-ce pas ? On dirait presque qu'il est vivant.", "Du hast es gefunden. Schön anzusehen, nicht wahr? Es wirkt fast lebendig.", "Você o encontrou. É bonito, não é? Parece quase vivo.", "Ты нашёл его. Красивый, правда? Будто живой.", "你找到了。很漂亮，不是吗？它几乎像是活的。" },
        ["dlg.q5.05"] = new[] { "Tienilo. La guardia è finita da tempo. Forse ne servirà una nuova.", "Keep it. The guard ended long ago. Perhaps a new one will be needed.", "Quédatelo. La guardia terminó hace tiempo. Quizá haga falta una nueva.", "Garde-le. La garde a pris fin il y a longtemps. Il en faudra peut-être une nouvelle.", "Behalte es. Die Wache ist längst vorbei. Vielleicht braucht es eine neue.", "Fique com ele. A guarda acabou há muito tempo. Talvez seja preciso uma nova.", "Оставь его себе. Стража давно кончилась. Возможно, понадобится новая.", "留着吧。守卫早已不复存在，也许需要一位新的守卫。" },
        ["dlg.q5.06"] = new[] { "Un tunnel a est, dici? Graffi sui muri... e impronte bagnate che finiscono contro la roccia?", "A tunnel to the east, you say? Scratches on the walls... and wet footprints that end against the rock?", "¿Un túnel al este, dices? Arañazos en los muros... ¿y huellas mojadas que terminan contra la roca?", "Un tunnel à l'est, dis-tu ? Des griffures sur les murs... et des empreintes mouillées qui s'arrêtent contre la roche ?", "Ein Tunnel im Osten, sagst du? Kratzer an den Wänden... und nasse Spuren, die vor dem Fels enden?", "Um túnel a leste, você diz? Arranhões nas paredes... e pegadas molhadas que terminam na rocha?", "Тоннель на востоке, говоришь? Царапины на стенах... и мокрые следы, что обрываются у скалы?", "你说东边有条隧道？墙上有抓痕……还有湿漉漉的脚印，一直走到岩壁就没了？" },
        ["dlg.q5.07"] = new[] { "No. Non so chi le abbia lasciate. E prego di non scoprirlo mai.", "No. I don't know who left them. And I pray I never find out.", "No. No sé quién las dejó. Y rezo por no descubrirlo nunca.", "Non. Je ne sais pas qui les a laissées. Et je prie pour ne jamais le découvrir.", "Nein. Ich weiß nicht, wer sie hinterlassen hat. Und ich bete, dass ich es nie erfahre.", "Não. Não sei quem as deixou. E rezo para nunca descobrir.", "Нет. Не знаю, кто их оставил. И молюсь, чтобы никогда не узнать.", "不，我不知道是谁留下的。我祈祷永远不要知道。" },
        ["zona.taverna"] = new[] { "Taverna di Hobb", "Hobb's Tavern", "Taberna de Hobb", "Taverne de Hobb", "Hobbs Taverne", "Taverna do Hobb", "Таверна Хобба", "霍布的酒馆" },
        ["hud.entra_taverna"] = new[] { "Entra nella taverna", "Enter the tavern", "Entrar en la taberna", "Entrer dans la taverne", "Taverne betreten", "Entrar na taverna", "Войти в таверну", "进入酒馆" },
        ["hud.esci_taverna"] = new[] { "Esci dalla taverna", "Leave the tavern", "Salir de la taberna", "Sortir de la taverne", "Taverne verlassen", "Sair da taverna", "Выйти из таверны", "离开酒馆" },
        ["ob.q6.taverna"] = new[] { "Al tramonto, raggiungi la taverna di Hobb", "At sunset, go to Hobb's tavern", "Al atardecer, ve a la taberna de Hobb", "Au coucher du soleil, rends-toi à la taverne de Hobb", "Geh bei Sonnenuntergang zu Hobbs Taverne", "Ao pôr do sol, vá à taverna do Hobb", "На закате отправляйся в таверну Хобба", "日落时分，前往霍布的酒馆" },
        ["ob.q6.hobb"] = new[] { "Siediti al bancone con Hobb", "Sit at the counter with Hobb", "Siéntate en la barra con Hobb", "Assieds-toi au comptoir avec Hobb", "Setz dich zu Hobb an den Tresen", "Sente-se no balcão com o Hobb", "Присядь у стойки рядом с Хоббом", "到吧台和霍布坐一坐" },
        ["ob.q6.esci"] = new[] { "Esci dalla taverna", "Leave the tavern", "Sal de la taberna", "Sors de la taverne", "Verlasse die Taverne", "Saia da taverna", "Выйди из таверны", "离开酒馆" },
        ["dlg.q6.01"] = new[] { "Siediti. Stasera la birra è buona e le notizie sono cattive.", "Sit down. Tonight the beer is good and the news is bad.", "Siéntate. Esta noche la cerveza es buena y las noticias son malas.", "Assieds-toi. Ce soir la bière est bonne et les nouvelles sont mauvaises.", "Setz dich. Heute Abend ist das Bier gut und die Nachrichten schlecht.", "Sente-se. Hoje a cerveja está boa e as notícias estão ruins.", "Садись. Сегодня пиво хорошее, а новости плохие.", "坐吧。今晚啤酒不错，消息却很糟。" },
        ["dlg.q6.02"] = new[] { "Un mercante è passato dal bosco. Dice di aver visto fuochi nella foresta, e di aver sentito dei tamburi.", "A merchant came through the woods. He says he saw fires in the forest, and heard drums.", "Un mercader pasó por el bosque. Dice que vio fuegos en la espesura y que oyó tambores.", "Un marchand est passé par les bois. Il dit avoir vu des feux dans la forêt, et entendu des tambours.", "Ein Händler kam durch den Wald. Er sagt, er habe Feuer im Forst gesehen und Trommeln gehört.", "Um mercador passou pelo bosque. Diz que viu fogueiras na floresta e ouviu tambores.", "Через лес проходил торговец. Говорит, видел в чаще огни и слышал барабаны.", "有个商人穿过树林来的。他说在林子里看见了火光，还听见了鼓声。" },
        ["dlg.q6.03"] = new[] { "Io gli ho detto che era ubriaco. Lui mi ha risposto che non beve mai.", "I told him he was drunk. He told me he never drinks.", "Le dije que estaba borracho. Me respondió que nunca bebe.", "Je lui ai dit qu'il était ivre. Il m'a répondu qu'il ne boit jamais.", "Ich hab ihm gesagt, er sei betrunken. Er meinte, er trinke nie.", "Eu disse que ele estava bêbado. Ele respondeu que nunca bebe.", "Я сказал ему, что он пьян. А он ответил, что никогда не пьёт.", "我说他喝醉了。他说他从来滴酒不沾。" },
        ["dlg.q6.04"] = new[] { "Eccoti. Ti ho cercato dappertutto. Andiamo a casa, qui fa un caldo che non si respira.", "There you are. I've looked everywhere for you. Let's go home, it's so hot in here I can't breathe.", "Aquí estás. Te he buscado por todas partes. Vamos a casa, aquí hace un calor que no se respira.", "Te voilà. Je t'ai cherché partout. Rentrons, il fait si chaud ici qu'on étouffe.", "Da bist du. Ich habe dich überall gesucht. Lass uns heimgehen, hier ist es so heiß, dass man kaum atmen kann.", "Aí está você. Procurei por toda parte. Vamos para casa, aqui está tão quente que não dá para respirar.", "Вот ты где. Я тебя везде искала. Пойдём домой, тут так душно, что не вздохнуть.", "你在这儿啊。我到处找你。回家吧，这里热得喘不过气。" },
        ["dlg.q6.05"] = new[] { "Ho sentito la storia dei tamburi. Domani ne parliamo, va bene? Stasera... stasera restiamo insieme.", "I heard the story about the drums. We'll talk about it tomorrow, all right? Tonight... tonight we stay together.", "He oído la historia de los tambores. Mañana hablamos, ¿vale? Esta noche... esta noche nos quedamos juntos.", "J'ai entendu l'histoire des tambours. On en parlera demain, d'accord ? Ce soir... ce soir on reste ensemble.", "Ich habe die Geschichte mit den Trommeln gehört. Morgen reden wir darüber, ja? Heute Nacht... heute Nacht bleiben wir zusammen.", "Ouvi a história dos tambores. Amanhã a gente conversa, está bem? Hoje... hoje ficamos juntos.", "Я слышала про барабаны. Поговорим завтра, ладно? А сегодня... сегодня мы будем вместе.", "我听说了鼓声的事。明天再说，好吗？今晚……今晚我们待在一起。" },
        ["dlg.q6.06"] = new[] { "...Avete sentito anche voi?", "...Did you hear that too?", "...¿Lo habéis oído también?", "...Vous avez entendu, vous aussi ?", "...Habt ihr das auch gehört?", "...Vocês também ouviram?", "...Вы тоже это слышали?", "……你们也听见了吗？" },
        ["dlg.q6.07"] = new[] { "Dentro. Tutti dentro.", "Inside. Everyone inside.", "Dentro. Todos dentro.", "À l'intérieur. Tout le monde à l'intérieur.", "Rein. Alle rein.", "Para dentro. Todos para dentro.", "Внутрь. Все внутрь.", "进屋。所有人都进屋。" },
        ["nem.orco"] = new[] { "Orco razziatore", "Orc raider", "Orco saqueador", "Orque pillard", "Ork-Plünderer", "Orc saqueador", "Орк-налётчик", "兽人掠夺者" },
        ["nem.orco_corazzato"] = new[] { "Orco corazzato", "Armored orc", "Orco acorazado", "Orque cuirassé", "Gepanzerter Ork", "Orc encouraçado", "Бронированный орк", "重甲兽人" },
        ["nem.orco_enorme"] = new[] { "Orco enorme", "Enormous orc", "Orco enorme", "Orque colossal", "Riesiger Ork", "Orc enorme", "Огромный орк", "巨型兽人" },
        ["ob.razzia.prima"] = new[] { "Respingi gli orchi: {0} da abbattere", "Drive back the orcs: {0} to bring down", "Rechaza a los orcos: quedan {0} por abatir", "Repousse les orques : encore {0} à abattre", "Treib die Orks zurück: noch {0} zu besiegen", "Repila os orcs: faltam {0} para derrubar", "Отбрось орков: осталось сразить {0}", "击退兽人：还需击倒 {0} 个" },
        ["ob.razzia.attesa"] = new[] { "Gli orchi si ritirano. Preparati", "The orcs are retreating. Get ready", "Los orcos se retiran. Prepárate", "Les orques battent en retraite. Prépare-toi", "Die Orks ziehen sich zurück. Mach dich bereit", "Os orcs estão recuando. Prepare-se", "Орки отступают. Приготовься", "兽人正在撤退。做好准备" },
        ["ob.razzia.seconda"] = new[] { "Resisti alla seconda ondata: {0} da abbattere", "Hold against the second wave: {0} to bring down", "Resiste a la segunda oleada: quedan {0} por abatir", "Tiens face à la deuxième vague : encore {0} à abattre", "Halte der zweiten Welle stand: noch {0} zu besiegen", "Resista à segunda onda: faltam {0} para derrubar", "Выстой против второй волны: осталось сразить {0}", "抵挡第二波攻势：还需击倒 {0} 个" },
        ["ob.razzia.cerca"] = new[] { "Cerca i sopravvissuti nel villaggio", "Search the village for survivors", "Busca supervivientes en la aldea", "Cherche des survivants dans le village", "Such im Dorf nach Überlebenden", "Procure sobreviventes na vila", "Ищи выживших в деревне", "在村里寻找幸存者" },
        ["ob.razzia.enorme"] = new[] { "Qualcosa di enorme è in piazza", "Something enormous is in the square", "Algo enorme está en la plaza", "Quelque chose d'énorme est sur la place", "Etwas Riesiges ist auf dem Platz", "Algo enorme está na praça", "На площади что-то огромное", "广场上有个庞然大物" },
        ["msg.razzia.inizio"] = new[] { "Il villaggio brucia. Gli orchi sono già qui.", "The village is burning. The orcs are already here.", "La aldea arde. Los orcos ya están aquí.", "Le village brûle. Les orques sont déjà là.", "Das Dorf brennt. Die Orks sind schon da.", "A vila está em chamas. Os orcs já estão aqui.", "Деревня горит. Орки уже здесь.", "村子在燃烧。兽人已经来了。" },
        ["msg.razzia.ritirata"] = new[] { "Gli orchi battono in ritirata!", "The orcs are falling back!", "¡Los orcos se baten en retirada!", "Les orques battent en retraite !", "Die Orks treten den Rückzug an!", "Os orcs batem em retirada!", "Орки отступают!", "兽人撤退了！" },
        ["msg.razzia.tamburi"] = new[] { "Tamburi dal bosco... stanno tornando.", "Drums from the woods... they're coming back.", "Tambores en el bosque... están volviendo.", "Des tambours dans les bois... ils reviennent.", "Trommeln aus dem Wald... sie kommen zurück.", "Tambores no bosque... eles estão voltando.", "Барабаны в лесу... они возвращаются.", "林中传来鼓声……他们要回来了。" },
        ["msg.razzia.seconda"] = new[] { "Arriva la seconda ondata!", "The second wave is coming!", "¡Llega la segunda oleada!", "La deuxième vague arrive !", "Die zweite Welle kommt!", "Lá vem a segunda onda!", "Идёт вторая волна!", "第二波来了！" },
        ["msg.razzia.terremoto"] = new[] { "La terra trema...", "The ground is shaking...", "La tierra tiembla...", "La terre tremble...", "Die Erde bebt...", "A terra treme...", "Земля дрожит...", "大地在颤抖……" },
        ["msg.razzia.enorme"] = new[] { "Un orco enorme è piombato in piazza!", "An enormous orc has crashed into the square!", "¡Un orco enorme ha caído en la plaza!", "Un orque colossal s'est abattu sur la place !", "Ein riesiger Ork ist auf den Platz gestürzt!", "Um orc enorme despencou na praça!", "Огромный орк обрушился на площадь!", "一个巨型兽人砸落在广场上！" },
        ["dlg.dopo.edric5"] = new[] { "Porta quel medaglione con rispetto. Chi lo indossava non ha mai abbassato lo sguardo dal lago.", "Wear that medallion with respect. Its bearer never once looked away from the lake.", "Lleva ese medallón con respeto. Quien lo llevaba nunca apartó la vista del lago.", "Porte ce médaillon avec respect. Celui qui le portait n'a jamais détourné les yeux du lac.", "Trag das Medaillon mit Respekt. Wer es trug, hat den Blick nie vom See abgewandt.", "Use esse medalhão com respeito. Quem o usava nunca tirou os olhos do lago.", "Носи этот медальон с уважением. Его владелец ни разу не отвёл взгляда от озера.", "请怀着敬意佩戴那枚徽章。它的主人从未将目光从湖面移开。" },
        ["ob.q5.edric"] = new[] { "Parla con Edric al tempio", "Talk to Edric at the temple", "Habla con Edric en el templo", "Parle à Edric au temple", "Sprich mit Edric im Tempel", "Fale com Edric no templo", "Поговори с Эдриком в храме", "去神殿和埃德里克谈谈" },
        ["ob.q5.cripta"] = new[] { "Scendi nella cripta sotto il cimitero", "Go down into the crypt beneath the graveyard", "Baja a la cripta bajo el cementerio", "Descends dans la crypte sous le cimetière", "Steig in die Gruft unter dem Friedhof hinab", "Desça à cripta sob o cemitério", "Спустись в склеп под кладбищем", "下到墓地下的墓穴" },
        ["ob.q5.tomba"] = new[] { "Trova la tomba della prima guardia", "Find the tomb of the first guard", "Encuentra la tumba de la primera guardia", "Trouve la tombe de la première garde", "Finde das Grab der ersten Wache", "Encontre o túmulo da primeira guarda", "Найди гробницу первой стражи", "找到初代守卫之墓" },
        ["ob.q5.cancello"] = new[] { "Trova il modo di aprire il cancello", "Find a way to open the gate", "Encuentra la forma de abrir la reja", "Trouve un moyen d'ouvrir la grille", "Finde einen Weg, das Gitter zu öffnen", "Encontre um jeito de abrir o portão", "Найди способ открыть решётку", "想办法打开铁门" },
        ["ob.q5.baule"] = new[] { "Apri il baule della prima guardia", "Open the first guard's chest", "Abre el cofre de la primera guardia", "Ouvre le coffre de la première garde", "Öffne die Truhe der ersten Wache", "Abra o baú da primeira guarda", "Открой сундук первой стражи", "打开初代守卫的宝箱" },
        ["ob.q5.esci"] = new[] { "Esci dalla cripta", "Leave the crypt", "Sal de la cripta", "Sors de la crypte", "Verlasse die Gruft", "Saia da cripta", "Выйди из склепа", "离开墓穴" },
        ["ob.q5.torna"] = new[] { "Porta il medaglione a Edric", "Bring the medallion to Edric", "Lleva el medallón a Edric", "Apporte le médaillon à Edric", "Bring das Medaillon zu Edric", "Leve o medalhão para Edric", "Отнеси медальон Эдрику", "把徽章带给埃德里克" },
        ["tip.q5.leva"] = new[] { "Premi {Interagisci} su una leva per tirarla: da qualche parte una porta si aprirà.", "Press {Interagisci} on a lever to pull it: somewhere a door will open.", "Pulsa {Interagisci} en una palanca para tirar de ella: en algún sitio se abrirá una puerta.", "Appuie sur {Interagisci} devant un levier pour le tirer : quelque part, une porte s'ouvrira.", "Drücke {Interagisci} an einem Hebel, um ihn zu ziehen: Irgendwo öffnet sich eine Tür.", "Pressione {Interagisci} em uma alavanca para puxá-la: em algum lugar uma porta vai se abrir.", "Нажми {Interagisci} у рычага, чтобы потянуть его: где-то откроется дверь.", "在拉杆旁按{Interagisci}拉动它：某处的门会打开。" },
        ["tip.q5.medaglione"] = new[] { "Gli amuleti si mettono nell'inventario ({Inventario}), nella casella Amuleto.", "Amulets go in the Amulet slot of your inventory ({Inventario}).", "Los amuletos se equipan en la casilla Amuleto del inventario ({Inventario}).", "Les amulettes se placent dans la case Amulette de l'inventaire ({Inventario}).", "Amulette kommen im Inventar ({Inventario}) in den Amulett-Platz.", "Os amuletos vão no espaço Amuleto do inventário ({Inventario}).", "Амулеты надеваются в ячейку «Амулет» в инвентаре ({Inventario}).", "护符可在背包（{Inventario}）的护符栏中装备。" },
        ["oggetto.medaglione_guardia.nome"] = new[] { "Medaglione della prima guardia", "Medallion of the First Guard", "Medallón de la primera guardia", "Médaillon de la première garde", "Medaillon der ersten Wache", "Medalhão da primeira guarda", "Медальон первой стражи", "初代守卫徽章" },
        ["oggetto.medaglione_guardia.descrizione"] = new[] { "Un disco di bronzo annerito con un occhio aperto inciso al centro. Chi lo porta resiste un po' di più e si riprende a ogni nemico abbattuto.", "A blackened bronze disc with an open eye carved at its centre. Its bearer endures a little more and recovers with every foe felled.", "Un disco de bronce ennegrecido con un ojo abierto grabado en el centro. Quien lo lleva resiste un poco más y se recupera con cada enemigo abatido.", "Un disque de bronze noirci, un œil ouvert gravé en son centre. Son porteur tient un peu mieux et se remet à chaque ennemi abattu.", "Eine geschwärzte Bronzescheibe mit einem offenen Auge in der Mitte. Wer sie trägt, hält etwas mehr aus und erholt sich bei jedem gefallenen Feind.", "Um disco de bronze enegrecido com um olho aberto gravado no centro. Quem o usa resiste um pouco mais e se recupera a cada inimigo abatido.", "Почерневший бронзовый диск с открытым глазом в центре. Владелец чуть выносливее и восстанавливается с каждым павшим врагом.", "一枚发黑的青铜圆盘，中央刻着一只睁开的眼睛。佩戴者更耐打一些，每击倒一个敌人都能恢复些许。" },
        ["dlg.q4.01"] = new[] { "Ah, il padre di Tobin. Entra, entra, ma non toccare niente.", "Ah, Tobin's father. Come in, come in, but don't touch anything.", "Ah, el padre de Tobin. Pasa, pasa, pero no toques nada.", "Ah, le père de Tobin. Entre, entre, mais ne touche à rien.", "Ah, Tobins Vater. Komm rein, komm rein, aber fass nichts an.", "Ah, o pai do Tobin. Entra, entra, mas não toque em nada.", "А, отец Тобина. Заходи, заходи, только ничего не трогай.", "啊，托宾的父亲。进来，进来，但什么都别碰。" },
        ["dlg.q4.02"] = new[] { "Mi servono tre fiori di riva. Crescono solo dove l'acqua è nera. Io alla mia età non mi bagno più i piedi.", "I need three shore flowers. They only grow where the water is black. At my age I don't get my feet wet anymore.", "Necesito tres flores de orilla. Solo crecen donde el agua es negra. A mi edad ya no me mojo los pies.", "Il me faut trois fleurs de rive. Elles ne poussent que là où l'eau est noire. À mon âge, je ne me mouille plus les pieds.", "Ich brauche drei Uferblumen. Sie wachsen nur dort, wo das Wasser schwarz ist. In meinem Alter mache ich mir keine nassen Füße mehr.", "Preciso de três flores da margem. Só crescem onde a água é negra. Na minha idade, não molho mais os pés.", "Мне нужны три прибрежных цветка. Они растут только там, где вода чёрная. В мои годы я уже ноги не мочу.", "我需要三朵岸花。它们只长在水发黑的地方。我这把年纪，可不再下水湿脚了。" },
        ["dlg.q4.03"] = new[] { "Non fidarti dell'acqua. Io la guardo da una vita e non mi ha mai detto niente di buono.", "Don't trust the water. I've watched it all my life and it has never told me anything good.", "No te fíes del agua. La miro desde hace una vida y nunca me ha dicho nada bueno.", "Ne te fie pas à l'eau. Je la regarde depuis toujours et elle ne m'a jamais rien dit de bon.", "Trau dem Wasser nicht. Ich schaue es mein Leben lang an, und es hat mir nie etwas Gutes erzählt.", "Não confie na água. Eu olho para ela a vida inteira e ela nunca me disse nada de bom.", "Не доверяй воде. Я всю жизнь на неё смотрю, и ничего хорошего она мне не сказала.", "别相信这水。我看了它一辈子，它从没告诉过我什么好事。" },
        ["dlg.q4.04"] = new[] { "Perfetto, li hai trovati. Dammeli e scegli tu cosa ci preparo: con tre fiori di riva ti faccio due pozioni. Bevine una subito, che quei ratti ti hanno conciato male.", "Perfect, you found them. Hand them over and choose what I make: with three shore flowers I'll brew you two potions. Drink one right away, those rats gave you a beating.", "Perfecto, las encontraste. Dámelas y elige qué te preparo: con tres flores de orilla te hago dos pociones. Bébete una ya, que esas ratas te dejaron hecho polvo.", "Parfait, tu les as trouvées. Donne-les-moi et choisis ce que je te prépare : avec trois fleurs de rive, je te fais deux potions. Bois-en une tout de suite, ces rats t'ont bien amoché.", "Perfekt, du hast sie gefunden. Gib sie mir und such dir aus, was ich dir mische: Aus drei Uferblumen mache ich dir zwei Tränke. Trink gleich einen, die Ratten haben dich übel zugerichtet.", "Perfeito, você as encontrou. Me dê e escolha o que eu preparo: com três flores da margem faço duas poções. Beba uma agora, aqueles ratos te deixaram em pedaços.", "Отлично, нашёл. Давай их сюда и выбирай, что приготовить: из трёх прибрежных цветов сварю тебе два зелья. Выпей одно сразу, крысы тебя здорово потрепали.", "很好，你找到了。把花给我，你来选我做什么：三朵岸花能给你熬两瓶药水。马上喝一瓶，那些老鼠把你伤得不轻。" },
        ["dlg.q4.05"] = new[] { "Da bambina ho visto qualcosa uscire dal lago... Non ho mai detto a nessuno che cosa fosse.", "When I was a little girl I saw something come out of the lake... I've never told anyone what it was.", "De niña vi algo salir del lago... Nunca le he dicho a nadie qué era.", "Petite, j'ai vu quelque chose sortir du lac... Je n'ai jamais dit à personne ce que c'était.", "Als kleines Mädchen habe ich etwas aus dem See steigen sehen ... Ich habe nie jemandem erzählt, was es war.", "Quando era menina, vi algo sair do lago... Nunca contei a ninguém o que era.", "В детстве я видела, как что-то вышло из озера... Я никому не говорила, что это было.", "我小时候见过有东西从湖里出来……我从没告诉过任何人那是什么。" },
        ["tip.q4.raccogli"] = new[] { "Premi {Interagisci} per raccogliere un oggetto: finisce nello zaino ({Inventario}).", "Press {Interagisci} to pick up an item: it goes into your bag ({Inventario}).", "Pulsa {Interagisci} para recoger un objeto: va a la mochila ({Inventario}).", "Appuie sur {Interagisci} pour ramasser un objet : il va dans ton sac ({Inventario}).", "Drücke {Interagisci}, um einen Gegenstand aufzuheben: Er landet in deinem Inventar ({Inventario}).", "Aperte {Interagisci} para pegar um item: ele vai para a mochila ({Inventario}).", "Нажми {Interagisci}, чтобы подобрать предмет: он попадёт в сумку ({Inventario}).", "按 {Interagisci} 拾取物品：它会放进背包（{Inventario}）。" },
        ["tip.q4.acqua"] = new[] { "I fiori crescono nell'acqua bassa della riva: lì si cammina più piano.", "The flowers grow in the shallow water by the shore: you walk slower there.", "Las flores crecen en el agua poco profunda de la orilla: allí se camina más despacio.", "Les fleurs poussent dans l'eau peu profonde de la rive : on y marche plus lentement.", "Die Blumen wachsen im seichten Wasser am Ufer: Dort geht man langsamer.", "As flores crescem na água rasa da margem: lá se anda mais devagar.", "Цветы растут на мелководье у берега: там идёшь медленнее.", "这些花长在岸边的浅水里：在那里走得会慢一些。" },
        ["tip.q4.usa"] = new[] { "Premi {UsaOggetto} per bere una pozione. Nello zaino ({Inventario}), scheda Varie, scegli quale oggetto usare.", "Press {UsaOggetto} to drink a potion. In your bag ({Inventario}), Misc tab, choose which item to use.", "Pulsa {UsaOggetto} para beber una poción. En la mochila ({Inventario}), pestaña Varios, elige qué objeto usar.", "Appuie sur {UsaOggetto} pour boire une potion. Dans ton sac ({Inventario}), onglet Divers, choisis l'objet à utiliser.", "Drücke {UsaOggetto}, um einen Trank zu trinken. Im Inventar ({Inventario}), Reiter Sonstiges, wählst du, welchen Gegenstand du benutzt.", "Aperte {UsaOggetto} para beber uma poção. Na mochila ({Inventario}), aba Diversos, escolha qual item usar.", "Нажми {UsaOggetto}, чтобы выпить зелье. В сумке ({Inventario}), вкладка «Разное», выбери, какой предмет использовать.", "按 {UsaOggetto} 喝药水。在背包（{Inventario}）的“杂项”标签里可以选择要使用的物品。" },
        ["ob.q4.scambia"] = new[] { "Scambia i fiori con le pozioni nella bottega di Ilse", "Trade the flowers for potions in Ilse's shop", "Cambia las flores por pociones en la tienda de Ilse", "Échange les fleurs contre des potions dans la boutique d'Ilse", "Tausche die Blumen in Ilses Laden gegen Tränke", "Troque as flores por poções na loja de Ilse", "Обменяй цветы на зелья в лавке Ильзе", "在伊尔莎的店里用花换药水" },
        ["tip.q4.bottega"] = new[] { "Nella bottega scegli una voce e premi {Interagisci}. Con il baratto ogni fiore, o insieme di fiori, dà una pozione diversa; senza fiori puoi comprare con le monete d'oro, ma costa di più.", "In the shop, pick an entry and press {Interagisci}. With barter each flower, or mix of flowers, makes a different potion; without flowers you can buy with gold coins, but it costs more.", "En la tienda, elige una opción y pulsa {Interagisci}. Con el trueque cada flor, o mezcla de flores, da una poción distinta; sin flores puedes comprar con monedas de oro, pero cuesta más.", "Dans la boutique, choisis une entrée et appuie sur {Interagisci}. Avec le troc, chaque fleur, ou mélange de fleurs, donne une potion différente ; sans fleurs, tu peux acheter avec des pièces d'or, mais c'est plus cher.", "Wähle im Laden einen Eintrag und drücke {Interagisci}. Beim Tausch ergibt jede Blume oder Blumenmischung einen anderen Trank; ohne Blumen kannst du mit Goldmünzen kaufen, aber das kostet mehr.", "Na loja, escolha uma opção e pressione {Interagisci}. No escambo cada flor, ou mistura de flores, dá uma poção diferente; sem flores você pode comprar com moedas de ouro, mas custa mais.", "В лавке выбери пункт и нажми {Interagisci}. При обмене каждый цветок или смесь цветов даёт своё зелье; без цветов можно купить за золотые монеты, но дороже.", "在店里选择一项，按{Interagisci}。以物易物时，每种花或花的组合都能做出不同的药水；没有花也可以用金币购买，但更贵。" },
