        ["oggetto.cardo_nero.nome"] = new[] { "Cardo nero", "Black thistle", "Cardo negro", "Chardon noir", "Schwarze Distel", "Cardo-negro", "Чёрный чертополох", "黑蓟" },
        ["oggetto.cardo_nero.descrizione"] = new[] { "Spine scure e un fiore viola cupo. Cresce fra i sassi, nei campi incolti: chi ne beve il succo diventa duro come la pietra.", "Dark thorns and a deep purple bloom. It grows among the stones, in wild fields: whoever drinks its juice becomes hard as rock.", "Espinas oscuras y una flor púrpura intensa. Crece entre las piedras, en los campos baldíos: quien bebe su jugo se vuelve duro como la roca.", "Des épines sombres et une fleur d'un violet profond. Il pousse entre les pierres, dans les champs en friche : qui boit son suc devient dur comme la roche.", "Dunkle Dornen und eine tiefviolette Blüte. Sie wächst zwischen den Steinen auf brachliegenden Feldern: Wer ihren Saft trinkt, wird hart wie Fels.", "Espinhos escuros e uma flor roxa intensa. Cresce entre as pedras, nos campos abandonados: quem bebe seu suco fica duro como rocha.", "Тёмные шипы и густо-фиолетовый цветок. Растёт среди камней на заброшенных полях: кто выпьет его сок, становится твёрдым, как скала.", "深色的刺，暗紫色的花。生长在荒地的石头间：喝下它的汁液，人会变得像岩石一样坚硬。" },
        ["oggetto.lunaria.nome"] = new[] { "Lunaria", "Moonwort", "Lunaria", "Lunaire", "Mondraute", "Lunária", "Лунник", "月光草" },
        ["oggetto.lunaria.descrizione"] = new[] { "Petali d'argento sottili come carta. Si apre solo di notte, vicino alle tombe e alle rovine. Gli stregoni la cercano per la magia.", "Paper-thin, silver petals. It only opens at night, near graves and ruins. Sorcerers seek it for their magic.", "Pétalos plateados, finos como el papel. Solo se abre de noche, cerca de tumbas y ruinas. Los hechiceros la buscan por su magia.", "Des pétales argentés, fins comme du papier. Elle ne s'ouvre que la nuit, près des tombes et des ruines. Les sorciers la recherchent pour leur magie.", "Silberne Blütenblätter, dünn wie Papier. Sie öffnet sich nur nachts, nahe Gräbern und Ruinen. Hexer suchen sie für ihre Magie.", "Pétalas prateadas, finas como papel. Só se abre à noite, perto de túmulos e ruínas. Os feiticeiros a procuram por sua magia.", "Серебристые лепестки, тонкие как бумага. Раскрывается только ночью, у могил и руин. Колдуны ищут его ради магии.", "花瓣银白，薄如纸。只在夜里绽放，长在墓地和废墟旁。术士们为了魔力而寻找它。" },
        ["oggetto.tonico_di_cardo.nome"] = new[] { "Tonico di cardo", "Thistle tonic", "Tónico de cardo", "Tonique de chardon", "Distel-Tonikum", "Tônico de cardo", "Чертополоховый тоник", "蓟草补剂" },
        ["oggetto.tonico_di_cardo.descrizione"] = new[] { "Amaro da far lacrimare. Per qualche minuto la pelle si fa dura come la pietra e i colpi fanno meno male.", "Bitter enough to make you tear up. For a few minutes your skin turns hard as stone and blows hurt less.", "Tan amargo que hace llorar. Durante unos minutos la piel se vuelve dura como la piedra y los golpes duelen menos.", "Si amer qu'il fait pleurer. Pendant quelques minutes, la peau devient dure comme la pierre et les coups font moins mal.", "So bitter, dass einem die Tränen kommen. Ein paar Minuten lang wird die Haut hart wie Stein und Schläge tun weniger weh.", "Tão amargo que dá vontade de chorar. Por alguns minutos a pele fica dura como pedra e os golpes doem menos.", "Такой горький, что слёзы наворачиваются. На несколько минут кожа становится твёрдой, как камень, и удары ранят меньше.", "苦得让人流泪。几分钟内，皮肤会变得像石头一样硬，挨打也没那么疼。" },
        ["oggetto.infuso_di_lunaria.nome"] = new[] { "Infuso di lunaria", "Moonwort infusion", "Infusión de lunaria", "Infusion de lunaire", "Mondrauten-Aufguss", "Infusão de lunária", "Настой лунника", "月光草浸剂" },
        ["oggetto.infuso_di_lunaria.descrizione"] = new[] { "Azzurro e freddo come la luna. Per qualche minuto la magia trova più spazio dentro di te.", "Blue and cold as the moon. For a few minutes magic finds more room inside you.", "Azul y frío como la luna. Durante unos minutos la magia encuentra más espacio dentro de ti.", "Bleue et froide comme la lune. Pendant quelques minutes, la magie trouve plus de place en toi.", "Blau und kalt wie der Mond. Ein paar Minuten lang findet die Magie mehr Raum in dir.", "Azul e fria como a lua. Por alguns minutos a magia encontra mais espaço dentro de você.", "Синий и холодный, как луна. На несколько минут магии становится в тебе просторнее.", "像月亮一样蓝而冰冷。几分钟内，魔力会在你体内找到更多空间。" },
        ["oggetto.balsamo_di_riva.nome"] = new[] { "Balsamo di riva", "Shore balm", "Bálsamo de orilla", "Baume de rive", "Uferbalsam", "Bálsamo da margem", "Прибрежный бальзам", "岸花香膏" },
        ["oggetto.balsamo_di_riva.descrizione"] = new[] { "Denso e profumato di resina. Chiude le ferite piano piano e indurisce la pelle.", "Thick and smelling of resin. It slowly closes wounds and toughens the skin.", "Espeso y con olor a resina. Cierra las heridas poco a poco y endurece la piel.", "Épais et parfumé à la résine. Il referme lentement les blessures et durcit la peau.", "Dick und nach Harz duftend. Er schließt Wunden langsam und härtet die Haut.", "Denso e com cheiro de resina. Fecha as feridas aos poucos e endurece a pele.", "Густой, пахнет смолой. Понемногу закрывает раны и закаляет кожу.", "浓稠，带着树脂的香气。慢慢愈合伤口，让皮肤变得坚韧。" },
        ["oggetto.elisir_del_crepuscolo.nome"] = new[] { "Elisir del crepuscolo", "Twilight elixir", "Elixir del crepúsculo", "Élixir du crépuscule", "Dämmerungselixier", "Elixir do crepúsculo", "Эликсир сумерек", "暮光灵药" },
        ["oggetto.elisir_del_crepuscolo.descrizione"] = new[] { "Viola come il cielo dopo il tramonto. Un sorso di tutto: ferite chiuse, pelle dura e più spazio per la magia.", "Purple as the sky after sunset. A sip of everything: closed wounds, tough skin and more room for magic.", "Morado como el cielo tras el ocaso. Un sorbo de todo: heridas cerradas, piel dura y más espacio para la magia.", "Violet comme le ciel après le coucher du soleil. Une gorgée de tout : blessures refermées, peau dure et plus de place pour la magie.", "Violett wie der Himmel nach Sonnenuntergang. Ein Schluck von allem: geschlossene Wunden, harte Haut und mehr Raum für Magie.", "Roxo como o céu depois do pôr do sol. Um gole de tudo: feridas fechadas, pele dura e mais espaço para a magia.", "Фиолетовый, как небо после заката. Глоток всего сразу: закрытые раны, твёрдая кожа и простор для магии.", "紫得像日落后的天空。一口包含一切：愈合伤口、坚硬皮肤，还有更多魔力空间。" },
        ["ob.q2.brannoc"] = new[] { "Parla con il fabbro Brannoc", "Talk to Brannoc the smith", "Habla con el herrero Brannoc", "Parle au forgeron Brannoc", "Sprich mit dem Schmied Brannoc", "Fale com o ferreiro Brannoc", "Поговори с кузнецом Бренноком", "和铁匠布兰诺克谈谈" },
        ["ob.q2.allenati"] = new[] { "Allenati sul manichino di Brannoc", "Train on Brannoc's dummy", "Entrena con el muñeco de Brannoc", "Entraîne-toi sur le mannequin de Brannoc", "Trainiere an Brannocs Übungspuppe", "Treine no boneco do Brannoc", "Потренируйся на чучеле Бреннока", "在布兰诺克的木人上练习" },
        ["ob.q2.tempio"] = new[] { "Vai al tempio dal vecchio Edric", "Go to old Edric at the temple", "Ve al templo a ver al viejo Edric", "Va voir le vieil Edric au temple", "Geh zum alten Edric in den Tempel", "Vá ao templo falar com o velho Edric", "Иди в храм к старому Эдрику", "去神殿找老埃德里克" },
        ["ob.q2.studia"] = new[] { "Prova gli incantesimi sui bersagli di Edric", "Try your spells on Edric's targets", "Prueba los hechizos en los blancos de Edric", "Essaie tes sorts sur les cibles d'Edric", "Probiere deine Zauber an Edrics Zielscheiben aus", "Teste os feitiços nos alvos de Edric", "Испытай заклинания на мишенях Эдрика", "在埃德里克的靶子上试试法术" },
