        ["oggetto.spada_vecchia_vita.nome"] = new[] { "Spada della vecchia vita", "Sword of the Old Life", "Espada de la vieja vida", "Épée de l'ancienne vie", "Schwert des alten Lebens", "Espada da vida antiga", "Меч прежней жизни", "旧日之剑" },
        ["oggetto.spada_vecchia_vita.descrizione"] = new[]
        {
            "La spada che avevi appeso al muro. Pensavi di non doverla impugnare mai più.",
            "The sword you had hung on the wall. You thought you would never have to hold it again.",
            "La espada que habías colgado en la pared. Creías que nunca tendrías que volver a empuñarla.",
            "L'épée que tu avais accrochée au mur. Tu pensais ne plus jamais devoir la tenir.",
            "Das Schwert, das du an die Wand gehängt hattest. Du dachtest, du müsstest es nie wieder führen.",
            "A espada que você tinha pendurado na parede. Achava que nunca mais precisaria empunhá-la.",
            "Меч, который ты повесил на стену. Ты думал, что больше никогда не возьмёшь его в руки.",
            "你早已挂在墙上的剑。你以为再也不必握起它。",
        },
        // ---------- armi improvvisate della gattabuia (tutte le classi, Docs/gattabuia.md) ----------
        ["oggetto.osso_lungo.nome"] = new[] { "Osso lungo", "Long Bone", "Hueso largo", "Os long", "Langer Knochen", "Osso longo", "Длинная кость", "长骨" },
        ["oggetto.osso_lungo.descrizione"] = new[]
        {
            "Un femore raccolto fra i corpi della gattabuia. Leggero e veloce, ma colpisce poco e para male.",
            "A thighbone picked up among the bodies in the jail. Light and quick, but it hits weakly and blocks poorly.",
            "Un fémur recogido entre los cuerpos de la mazmorra. Ligero y rápido, pero golpea poco y bloquea mal.",
            "Un fémur ramassé parmi les corps de la geôle. Léger et rapide, mais il frappe peu et pare mal.",
            "Ein Oberschenkelknochen aus dem Kerker, zwischen den Leichen aufgelesen. Leicht und schnell, doch er trifft schwach und blockt schlecht.",
            "Um fêmur recolhido entre os corpos da masmorra. Leve e rápido, mas bate pouco e defende mal.",
            "Бедренная кость, подобранная среди тел в темнице. Лёгкая и быстрая, но бьёт слабо и плохо защищает.",
            "从牢中尸堆里捡来的一根大腿骨。轻巧迅速，但伤害低，格挡也差。",
        },
        ["oggetto.catenaccio.nome"] = new[] { "Catenaccio", "Padlock Chain", "Cadena con candado", "Chaîne cadenassée", "Kettenschloss", "Corrente com cadeado", "Цепь с замком", "锁链" },
        ["oggetto.catenaccio.descrizione"] = new[]
        {
            "Una catena strappata dal muro di una cella, con il lucchetto ancora attaccato. Lenta e faticosa, ma arriva lontano e spazza tutto intorno.",
            "A chain torn from a cell wall, its padlock still attached. Slow and tiring, but it reaches far and sweeps all around.",
            "Una cadena arrancada del muro de una celda, con el candado aún puesto. Lenta y agotadora, pero llega lejos y barre todo alrededor.",
            "Une chaîne arrachée au mur d'une cellule, le cadenas encore accroché. Lente et épuisante, mais elle porte loin et balaie tout autour.",
            "Eine aus der Zellenwand gerissene Kette, das Schloss hängt noch daran. Langsam und kräftezehrend, doch sie reicht weit und fegt alles ringsum.",
            "Uma corrente arrancada da parede de uma cela, com o cadeado ainda preso. Lenta e cansativa, mas alcança longe e varre tudo em volta.",
            "Цепь, вырванная из стены камеры, с ещё висящим замком. Медленная и утомительная, но бьёт далеко и сметает всё вокруг.",
            "从牢房墙上扯下的锁链，挂锁还在上面。笨重费力，但攻击范围远，能横扫四周。",
        },
        ["oggetto.mannaia_macellaio.nome"] = new[] { "Mannaia del macellaio", "Butcher's Cleaver", "Cuchilla del carnicero", "Couperet du boucher", "Fleischerbeil", "Cutelo do açougueiro", "Тесак мясника", "屠夫砍刀" },
        ["oggetto.mannaia_macellaio.descrizione"] = new[]
        {
            "La lama larga degli orchi macellai, ancora sporca. Taglia bene da vicino, ma è corta e non passa le armature.",
            "The broad blade of the orc butchers, still filthy. It cuts well up close, but it is short and does not pierce armour.",
            "La hoja ancha de los orcos carniceros, todavía sucia. Corta bien de cerca, pero es corta y no atraviesa armaduras.",
            "La large lame des orcs bouchers, encore souillée. Elle tranche bien de près, mais elle est courte et ne perce pas les armures.",
            "Die breite Klinge der Ork-Schlachter, noch verschmiert. Aus der Nähe schneidet sie gut, doch sie ist kurz und durchdringt keine Rüstung.",
            "A lâmina larga dos orcs açougueiros, ainda suja. Corta bem de perto, mas é curta e não atravessa armaduras.",
            "Широкий клинок орков-мясников, ещё грязный. Хорошо рубит вблизи, но короткий и не пробивает доспехи.",
            "兽人屠夫的宽刃，还沾着污秽。近身砍得狠，但刃短，破不了护甲。",
        },
        ["oggetto.pugnale_arrugginito.nome"] = new[] { "Pugnale arrugginito", "Rusty Dagger", "Puñal oxidado", "Dague rouillée", "Rostiger Dolch", "Punhal enferrujado", "Ржавый кинжал", "生锈匕首" },
        ["oggetto.pugnale_arrugginito.descrizione"] = new[]
        {
            "Una lama corta mangiata dalla ruggine. Velocissima e poco faticosa, ma colpisce pochissimo: bisogna stare addosso al nemico.",
            "A short blade eaten by rust. Very fast and barely tiring, but it hits very little: you must stay right on the enemy.",
            "Una hoja corta comida por el óxido. Rapidísima y poco agotadora, pero golpea muy poco: hay que pegarse al enemigo.",
            "Une lame courte rongée par la rouille. Très rapide et peu fatigante, mais elle frappe très peu : il faut coller à l'ennemi.",
            "Eine kurze, von Rost zerfressene Klinge. Sehr schnell und kaum anstrengend, doch sie trifft sehr schwach: Man muss am Gegner kleben.",
            "Uma lâmina curta comida pela ferrugem. Rapidíssima e pouco cansativa, mas bate muito pouco: é preciso ficar colado ao inimigo.",
            "Короткий клинок, изъеденный ржавчиной. Очень быстрый и почти не утомляет, но бьёт совсем слабо: держись вплотную к врагу.",
            "被锈蚀的短刃。极快且不费体力，但伤害极低，必须贴身作战。",
        },
        ["oggetto.mazza_chiodata.nome"] = new[] { "Mazza chiodata", "Spiked Club", "Maza con clavos", "Massue cloutée", "Nagelkeule", "Clava cravejada", "Шипастая дубина", "钉头棒" },
        ["oggetto.mazza_chiodata.descrizione"] = new[]
        {
            "Un bastone pesante pieno di chiodi storti. Il Carceriere la teneva per gli intrusi più testardi.",
            "A heavy club studded with bent nails. The Jailer kept it for the most stubborn intruders.",
            "Un garrote pesado lleno de clavos torcidos. El Carcelero la guardaba para los intrusos más tercos.",
            "Un lourd gourdin hérissé de clous tordus. Le Geôlier la gardait pour les intrus les plus têtus.",
            "Eine schwere Keule voller krummer Nägel. Der Kerkermeister hob sie für die stursten Eindringlinge auf.",
            "Um porrete pesado cheio de pregos tortos. O Carcereiro a guardava para os intrusos mais teimosos.",
            "Тяжёлая дубина, утыканная кривыми гвоздями. Тюремщик берёг её для самых упрямых незваных гостей.",
            "一根钉满弯钉的沉重木棒。狱卒专门留着对付最顽固的闯入者。",
        },
        ["oggetto.mannaia_affilata.nome"] = new[] { "Mannaia affilata", "Sharpened Cleaver", "Cuchilla afilada", "Couperet affûté", "Geschärftes Hackbeil", "Cutelo afiado", "Заточенный тесак", "磨利砍刀" },
        ["oggetto.mannaia_affilata.descrizione"] = new[]
        {
            "Una mannaia da macellaio ripassata sulla pietra. Taglia più a fondo, ma pesa e va caricata con calma.",
            "A butcher's cleaver run over the whetstone. It cuts deeper, but it is heavy and slow to swing.",
            "Una cuchilla de carnicero pasada por la piedra. Corta más hondo, pero pesa y hay que cargarla con calma.",
            "Un couperet de boucher repassé sur la pierre. Il tranche plus profond, mais il pèse et se lève lentement.",
            "Ein Fleischerbeil, frisch am Stein geschärft. Es schneidet tiefer, ist aber schwer und langsam im Schwung.",
            "Um cutelo de açougueiro passado na pedra. Corta mais fundo, mas pesa e precisa de calma para golpear.",
            "Тесак мясника, заточенный на камне. Рубит глубже, но тяжёлый и замахивается медленно.",
            "在磨石上磨过的屠夫砍刀。砍得更深，但沉重，挥动缓慢。",
        },
        ["oggetto.catena_carceriere.nome"] = new[] { "Catena del carceriere", "Jailer's Chains", "Cadenas del carcelero", "Chaînes du geôlier", "Ketten des Kerkermeisters", "Correntes do carcereiro", "Цепи тюремщика", "狱卒锁链" },
        ["oggetto.catena_carceriere.descrizione"] = new[]
        {
            "Le catene che stringevano il Carceriere, avvolte sul petto come un'armatura. Pesano, ma fermano i colpi.",
            "The chains that bound the Jailer, wrapped around the chest like armour. Heavy, but they stop blows.",
            "Las cadenas que ataban al Carcelero, enrolladas en el pecho como una armadura. Pesan, pero detienen los golpes.",
            "Les chaînes qui entravaient le Geôlier, enroulées sur la poitrine comme une armure. Lourdes, mais elles arrêtent les coups.",
            "Die Ketten, die den Kerkermeister fesselten, wie eine Rüstung um die Brust gewickelt. Schwer, doch sie halten Schläge auf.",
            "As correntes que prendiam o Carcereiro, enroladas no peito como uma armadura. Pesam, mas detêm os golpes.",
            "Цепи, сковывавшие Тюремщика, обмотанные вокруг груди как доспех. Тяжёлые, но держат удары.",
            "曾束缚狱卒的锁链，缠在胸前如同铠甲。沉重，却能挡住攻击。",
        },
        ["oggetto.dente_orco.nome"] = new[] { "Dente d'orco", "Orc Tooth", "Diente de orco", "Dent d'orc", "Orkzahn", "Dente de orc", "Зуб орка", "兽人之牙" },
        ["oggetto.dente_orco.descrizione"] = new[]
        {
            "Un dente giallo legato a uno spago. Ogni nemico abbattuto ti ridà un po' di vita.",
            "A yellow tooth tied to a string. Every enemy you fell gives you back a little health.",
            "Un diente amarillo atado a un cordel. Cada enemigo abatido te devuelve un poco de vida.",
            "Une dent jaune nouée à une ficelle. Chaque ennemi abattu te rend un peu de vie.",
            "Ein gelber Zahn an einer Schnur. Jeder besiegte Feind gibt dir ein wenig Leben zurück.",
            "Um dente amarelo amarrado a um barbante. Cada inimigo abatido devolve um pouco de vida.",
            "Жёлтый зуб на бечёвке. Каждый поверженный враг возвращает немного здоровья.",
            "一颗系在细绳上的黄牙。每击倒一名敌人，回复少许生命。",
        },
        ["oggetto.lacci_cuoio.nome"] = new[] { "Lacci di cuoio", "Leather Laces", "Cordones de cuero", "Lacets de cuir", "Lederschnüre", "Cordões de couro", "Кожаные шнурки", "皮革系带" },
        ["oggetto.lacci_cuoio.descrizione"] = new[]
        {
            "Lacci intrecciati stretti al polso. Ti aiutano a riprendere fiato un po' più in fretta.",
            "Laces braided tight around the wrist. They help you catch your breath a little faster.",
            "Cordones trenzados apretados a la muñeca. Te ayudan a recuperar el aliento un poco más rápido.",
            "Des lacets tressés serrés au poignet. Ils t'aident à reprendre ton souffle un peu plus vite.",
            "Fest ums Handgelenk geflochtene Schnüre. Sie helfen dir, etwas schneller zu Atem zu kommen.",
