        ["oggetto.pietra_focolare.nome"] = new[] { "Pietra del focolare", "Stone of the Hearth", "Piedra del hogar", "Pierre du foyer", "Herdstein", "Pedra da lareira", "Камень очага", "炉边之石" },
        ["oggetto.pietra_focolare.descrizione"] = new[]
        {
