        ["oggetto.sangue_antico.nome"] = new[] { "Sangue antico", "Ancient Blood", "Sangre antigua", "Sang ancien", "Uraltes Blut", "Sangue antigo", "Древняя кровь", "远古之血" },
        ["oggetto.sangue_antico.descrizione"] = new[]
        {
